    /* ------------------------------------------------------------------ R5: what to run */

    /** The live answer, computed in TrainerTab so the alarm receiver can ask the same
     *  question this screen asks - and so the ordering is asserted in the desktop
     *  self-test rather than only on a device. */
    private UpNext upNextNow(long now) {
        return TrainerTab.upNextNow(model, now, hasRemainderToday());
    }

    /** The routine a plan track would run right now: the second half when the first has
     *  already been done today, the first otherwise. */
    private String routineForTrack(int track, long now) {
        if (track == Plan.TRACK_FEEDER) return model.trainerFeederMintId;
        Model.TrainerTrackState st = track == Plan.TRACK_LENGTH
                ? model.trainerLength : model.trainerGirth;
        int ran = TrainerTab.trackRunsToday(model, track, now);
        if (ran >= 1 && TrainerTab.partsOf(model, st) == 2) return st.lastMintId2;
        return st.lastMintId;
    }

    /**
     * Mints a routine of exactly what is left and selects it.
     *
     * A REAL ROUTINE, not a resumed run. The pump has been off for hours, the app has been
     * closed, and pretending the earlier session is still open would mean restoring a plan
     * index into a table that no longer exists. What remains is a new session of the
     * remaining work, which is also what it is physically.
     *
     * IT WARMS UP AGAIN by default (your note): hours have passed and the tissue is cold.
     * The warm-up is an ordinary stage, so Skip still skips it mid-run.
     */
    private final class FinishRemainderTap implements View.OnClickListener {
        private final boolean warm;
        FinishRemainderTap(boolean warm) { this.warm = warm; }
        @Override public void onClick(View v) {
            if (!hasRemainderToday()) { showHome(); return; }
            Model.Routine src = model.routine(model.resumeRoutineId);
            int track = src.trainerTrack;
            Model.TrainerTrackState st = track == Plan.TRACK_LENGTH
                ? model.trainerLength : model.trainerGirth;
            long now = System.currentTimeMillis();
            TrainerEval e = evalTrack(track, st, now);
            if (e == null || e.rx == null) { showHome(); return; }
            /* WHAT IS LEFT, BUILT BY THE CORE (RxBuild#remainder): the cycles still owed at the
             * saved routine's own "Adjust first..." pressure where it was the track's routine
             * and still carries one (review L1), as many five-minute holds as are left under
             * the hybrid - never the whole hybrid again (review H1) - and never heavier than
             * the session it is the rest of: that is refused, not built. */
            boolean current = src.id.equals(st.lastMintId) || src.id.equals(st.lastMintId2);
            Mint.Adjust kept = current ? SavedMint.carried(st.lastMintSig, e.sig) : null;
            String id = RxBuild.remainder(model, src, e.rx, kept, model.resumeCycles, warm);
            if (id == null) {
                Ui.say(SessionActivity.this, "What is left would pull harder than "
                    + A11y.collapse(src.name) + " did, so it was not built \u2014 start it fresh "
                    + "instead", true);
                return;
            }
            // What it runs - a hybrid's holds are never more than the guidance's count.
            Mint.Rx rest = RxBuild.runsAs(model,
                RxBuild.remainderRx(e.rx, kept, model.resumeCycles), true);
            Model.Routine made = model.routine(id);
            if (made != null) {
                /* D4a - NAMED FROM WHAT IT RUNS. The body is built from TODAY's prescription,
                 * so the source routine's name - minted perhaps weeks ago at another pressure -
                 * stated a figure this routine does not command ("@ -5.9" over a -8.0 climb).
                 * The builder's own name says what it built. */
                made.name = made.name + "  \u00b7  the rest";
                made.mintedAs = "What was left of " + A11y.collapse(src.name) + " today.";
            }
            model.selected = id;
            model.resumeRoutineId = ""; model.resumeCycles = 0; model.resumeDayKey = 0;
            Store.save(SessionActivity.this, model);
            Ui.snack(SessionActivity.this, rootFrame, "Ready to finish \u2014 "
                + rest.sets + (rest.sets == 1 ? " cycle" : " cycles") + " left"
                + (warm ? ", after a warm-up" : ""));
            showHome();
        }
    }

    /** Drops the remainder without prejudice: the routine is untouched and still in the
     *  library, so "start it fresh" is simply the ordinary Today. */
    private final class DropRemainderTap implements View.OnClickListener {
        @Override public void onClick(View v) {
            model.resumeRoutineId = ""; model.resumeCycles = 0; model.resumeDayKey = 0;
            Store.save(SessionActivity.this, model);
            showHome();
        }
    }

    static final int SHAPE_WARM_MIN = 0, SHAPE_WARM_STEPS = 1, SHAPE_RET_KPA = 2,
                     SHAPE_RET_MIN = 3, SHAPE_REST = 4, SHAPE_BLOCK = 5, SHAPE_HOLD = 6,
                     SHAPE_PRIME = 7, SHAPE_EASE = 8, SHAPE_REST_TRAD = 9;

    final class ToggleRetention implements View.OnClickListener {
        @Override public void onClick(View v) {
            model.rxRetention = !model.rxRetention;
            Store.save(SessionActivity.this, model);
            showTrainer();
        }
    }

    /* ===================== D2 / F8 - ADJUST A MINT BEFORE SAVING IT ==================
     *
     * A mint was offered whole: save it or do not. A prescription that was nearly right had
     * to be saved and then edited in the library - and at that moment the app lost the
     * difference, because an edited routine is indistinguishable from one the plan never
     * wrote. The plan carried on scoring sessions against a prescription the routine no
     * longer matched.
     *
     * THE TWO VALUES THAT ARE ACTUALLY WORTH ARGUING WITH are the set count and the working
     * pressure. Everything else in a prescription is either derived from those (the net
     * target is sets x hold) or is the guide's own constant (the hold length, the drop, the
     * rest). Offering all of them would invite somebody to edit their way out of the plan
     * one field at a time; offering these two covers "not today" and "not that deep", which
     * is what a person actually knows that the plan does not.
     *
     * THE PRESSURE IS STILL CLAMPED by Mint#clampPressureKpa, exactly as the prescription's
     * own was - an adjustment is a preference, not a way past a limit.
     */
    int mintAdjSets, mintAdjKpa;

    AlertDialog mintAdjustDialog;

    /**
     * D2 - THE ONE PLACE A MINT IS FILED, adjusted or not.
     *
     * `sets` and `kpa` are what will actually be built, which for an unadjusted save are the
     * prescription's own. Everything that follows - advancing the track's working pressure,
     * accepting the decision, stamping the signature - happens identically either way,
     * because the difference between the two is what was BUILT, not how it was recorded.
     *
     * THE SIGNATURE IS STILL THE PRESCRIPTION'S. It is what stops the same prescription
     * being offered twice, and that question is about what the PLAN asked for - a person
     * choosing twelve sets instead of fourteen has still answered this week's offer, and
     * re-offering it because they did not take it verbatim would be nagging.
     *
     * THE WORKING PRESSURE ADVANCES TO WHAT WAS SAVED, not to what was prescribed. The
     * pressure the track carries forward has to be the one actually being trained at, or the
     * next prescription builds on a number nobody ran.
     */
    String saveMint(int track, TrainerEval e, int sets, int kpa, boolean open) {
        Model.TrainerTrackState state = (track == Plan.TRACK_LENGTH)
            ? model.trainerLength : model.trainerGirth;
        long now = System.currentTimeMillis();
        /* `sets` AND `kpa` ARE THE SHEET'S (review M1, M4): the figures it starts from are what
         * the plan's routine runs - the pressure with the Program's bias on it, a hybrid's
         * five-minute holds (RxBuild#adjustStartSets / #adjustStartKpa) - and Save passes them
         * unchanged. Moved off them, they are the person's. */
        boolean adjusted = RxBuild.adjustMoved(model, e.rx, sets, kpa);
        Mint.Rx use = RxBuild.adjustedRx(model, e.rx, sets, kpa);
        /* THE PRESSURE A PERSON SETS IS THEIRS (the owner's ruling, 0.10): the Program's Firm or
         * Gentle bias lands on the plan's own prescription, never on a pressure chosen here -
         * Firm used to put a pressure somebody had lowered straight back up to the band's top.
         * The day's cut and a gentle day's slower pull still apply, as to any trainer routine. */
        boolean ownKpa = RxBuild.adjustOwnKpa(model, e.rx, kpa);
        // Their set count too, where anything was adjusted: a hybrid of theirs keeps their
        // (lower) count of holds (review M4).
        boolean ownSets = adjusted;
        /* R1 - TWO ROUTINES WHEN THE PRESCRIPTION IS SPLIT, written together so a half
         * can never exist without its other half. Splitting is refused where it would be
         * meaningless: one set cannot be halved, and the feeder is ten minutes that is
         * already the short session a split exists to produce. */
        /* AND A TRACTION SESSION CANNOT BE HALVED. Its five blocks are a sequence -
         * release, pull, swap, expand - and half of it is not a smaller version of it.
         * RxBuild refuses the split for exactly this reason and simply ignores the part
         * arguments, so "two parts" minted TWO COMPLETE traction sessions and called them
         * halves: twice the work, under a name promising half. */
        boolean traction = use.track == Plan.TRACK_LENGTH
            && model.tractionShapeTag(System.currentTimeMillis()).length() > 0;
        boolean split = Mint.splitsInTwo(model.rxSplit, use.sets, use.track, traction);
        String id = split ? mintRoutineFromRx(use, 1, 2, ownKpa, ownSets)
                          : mintRoutineFromRx(use, 0, 0, ownKpa, ownSets);
        Model.Routine made = model.routine(id);
        if (made != null)
            made.mintedAs = adjusted ? mintAdjustSummaryFor(e, sets, kpa) : "";
        if (split) {
            String id2 = mintRoutineFromRx(use, 2, 2, ownKpa, ownSets);
            Model.Routine made2 = model.routine(id2);
            if (made2 != null)
                made2.mintedAs = adjusted ? mintAdjustSummaryFor(e, sets, kpa) : "";
            state.lastMintId2 = id2;
        } else {
            state.lastMintId2 = "";
        }
        state.lastMintId = id;
        /* AN ADJUSTED SAVE IS STILL THE PLAN'S ROUTINE (the owner's ruling, 0.10): the stored
         * signature records what was built - the person's pressure, the sets they chose - so
         * a fresh build of it is the same build and it never reads as edited, and a taper step
         * rebuilds it as they set it (SavedMint#carried). An unadjusted save stores e.sig. */
        state.lastMintSig = Mint.adjustedSignature(e.sig, use.sets, use.pressureKpa, ownKpa);
        state.lastMintMs = now;
        /* THE PLAN'S OWN FIGURE, OR THE PERSON'S: never the biased one the sheet shows, which
         * would ratchet the working pressure by the Program's bias at every save - and never
         * the scaled one (0.10), which would add the person's offset to the plan's figure at
         * every save. A pressure they set is kept on the plan's side of their offset, so the
         * next prescription is that pressure again (TrainerTab#savedPlanKpa). */
        state.setWorkingPressure(TrainerTab.savedPlanKpa(model, track, use, ownKpa, now), now);
        acceptDecision(track, e.decision, now);
        Mint.commitYield(state, track, e.decision, now);   // a saved yield change is kept
        editStageIdx = 0;
        Store.save(SessionActivity.this, model);
        // `open` is the card's save: say so and open the routine. The trainer setup's offer
        // saves several in a row and says so once itself (0.10).
        if (!open) return id;
        Ui.snack(SessionActivity.this, rootFrame,
            split ? "Saved to Library in two parts"
                  : adjusted ? "Saved to Library, adjusted" : "Saved to Library");
        showRoutEdit(id);
        return id;
    }

    /** The Trainer card's save: filed, said, and opened in the editor. */
    void saveMint(int track, TrainerEval e, int sets, int kpa) {
        saveMint(track, e, sets, kpa, true);
    }

    /** The recorded sentence, for a given pair - shared with the live preview so what is
     *  shown while choosing is exactly what is stored. */
    String mintAdjustSummaryFor(TrainerEval e, int sets, int kpa) {
        // Against what the sheet started from - the plan's routine as it runs (review M1, M4).
        int planSets = RxBuild.adjustStartSets(model, e.rx);
        int planKpa = RxBuild.adjustStartKpa(model, e.rx);
        if (sets == planSets && kpa == planKpa) return "";
        String unit = RxBuild.runsAs(model, e.rx) != e.rx ? " holds, not " : " sets, not ";
        StringBuilder b = new StringBuilder("Adjusted when saved: ");
        if (sets != planSets) b.append(sets).append(unit).append(planSets);
        if (sets != planSets && kpa != planKpa) b.append("; ");
        if (kpa != planKpa)
            b.append(Model.Fmt.p(kpa)).append(", not ").append(Model.Fmt.p(planKpa));
        return b.append(".").toString();
    }

    final class StartDeloadTap implements View.OnClickListener {
        private final int track;
        /** t10 R-23 / R-40 / R-64 - the week off a decision card offers starts from tomorrow
         *  (the next training morning), not at the tap: today's session, if there is one,
         *  still runs. The deload card's own "Start deload week" starts it now, as always. */
        private final boolean fromTomorrow;
        StartDeloadTap(int t) { this(t, false); }
        StartDeloadTap(int t, boolean tomorrow) { track = t; fromTomorrow = tomorrow; }
        @Override public void onClick(View v) {
            long now = System.currentTimeMillis();
            long from = fromTomorrow ? Deload.dayStartPlus(now, 1) : now;
            recordDeload(track, from, from + Plan.LAYOFF_MS, true, "deload week started",
                "deload week started — the plan’s week count pauses for 7 days");
            Ui.snack(SessionActivity.this, rootFrame,
                fromTomorrow ? "The week off starts tomorrow" : "Deload week started");
            showTrainer();
        }
    }

    /**
     * A DELOAD IS ON RECORD — tapped as it starts, or reported afterwards with its own dates.
     * One writer for both, because they mean the same thing to the plan: this rest was asked
     * for, so it costs no week, steps nothing back, and restarts the cadence.
     *
     * `gentle` arms the return taper. The tap always does; a report does when its switch is
     * on. The taper's steps start at the window's END, so a light session inside a deload week
     * runs gently without using one up.
     */
    void recordDeload(int track, long startMs, long endMs, boolean gentle, String rule,
                      String reason) {
        long now = System.currentTimeMillis();
        // Read the gap BEFORE the window moves: it is the stretch the prompt was asking about,
        // and answering it is what stops it being asked again.
        long gap = Deload.askGapStartMs(model, now);
        long last = TrainerTab.lastAnyPlanSessionMs(model);
        // The newest window AND the kept list the pressure clock asks: a deload week never
        // counts toward a pressure step (Deload#touches).
        Deload.remember(model, startMs, endMs);
        model.trainerFirstDeloadTaken = true;
        // THE DELOAD IS PLAN-WIDE, SO EVERY TRACK'S SUGGESTION IS ANSWERED (audit A15).
        boolean resolvedAny = false;
        for (int di = 0; di < model.trainerDecisions.size(); di++) {
            Model.TrainerDecision other = model.trainerDecisions.get(di);
            if (other == null) continue;
            if (other.action != Plan.ACTION_DELOAD) continue;
            if (other.state != Model.TrainerDecision.STATE_PENDING) continue;
            other.state = Model.TrainerDecision.STATE_ACCEPTED;
            resolvedAny = true;
        }
        // THE TRACK THAT ASKED, not the girth track by default. Every PENDING suggestion is
        // resolved above because a deload is plan-wide, but the row this files when there was
        // no pending one is a record of what somebody TAPPED - and the length card's own
        // "Start deload week" button is a real caller. Filing it under girth puts an entry in
        // the history against a track the user did not touch.
        Model.TrainerDecision latest = TrainerTab.latestDecisionForTrack(model, track);
        if (!resolvedAny && !(latest != null && latest.action == Plan.ACTION_DELOAD
                && latest.state == Model.TrainerDecision.STATE_ACCEPTED)) {
            Model.TrainerDecision d = new Model.TrainerDecision();
            d.track = track;
            d.action = Plan.ACTION_DELOAD; d.tag = Plan.TAG_INFERRED;
            d.rule = rule; d.reason = reason;
            d.ts = now; d.state = Model.TrainerDecision.STATE_ACCEPTED;
            model.addTrainerDecision(d);
        }
        // A WEEK THE PLAN NOW KNOWS WAS REST MUST NOT GO ON COSTING ONE.
        Deload.refund(model.trainerGirth, startMs, endMs);
        model.returnAnchorMs = last;                  // the automatic arming has its answer
        model.deloadAskAnchorMs = gap > 0L ? gap : last;
        // No signature is cleared - see the note above StayOneMoreDay. Arming moves today's
        // step into the signature, ending takes it out; a report saved with the switch off and
        // no step in force moves nothing, and so now rewrites nothing and announces nothing.
        if (gentle) Deload.arm(model, endMs); else Deload.end(model);
        Store.save(this, model);
    }

    /** Opens the report on a range, both ends local midnights. */
    void openDeloadSheet(long prefillFromMs, long prefillToMs) {
        DeloadSheet.open(this, prefillFromMs, prefillToMs);
    }

    /* ---- decision history recording (deduped) ---- */

    void acceptDecision(int track, Plan.Decision d, long now) {
        Model.TrainerDecision latest = TrainerTab.latestDecisionForTrack(model, track);
        if (latest != null && latest.action == d.action && latest.tag == d.tag
                && eqStr(latest.rule, d.rule)) {
            latest.state = Model.TrainerDecision.STATE_ACCEPTED;
            return;
        }
        Model.TrainerDecision rec = newDecision(track, d, now,
            Model.TrainerDecision.STATE_ACCEPTED);
        if (d.action == Plan.ACTION_HOLD) {
            rec.rule = "starting routine saved";
            rec.reason = "saved the starting routine to the library";
        }
        model.addTrainerDecision(rec);
    }

    static Model.TrainerDecision newDecision(int track, Plan.Decision d, long now,
                                                     int st) {
        Model.TrainerDecision rec = new Model.TrainerDecision();
        rec.track = track; rec.action = d.action; rec.tag = d.tag;
        rec.rule = d.rule; rec.reason = d.reason; rec.ts = now; rec.state = st;
        return rec;
    }

    private static boolean eqStr(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }

    /** O9 — which decisions the history is listing, and whether the twelve-row opening
     *  cap has been lifted. Neither is persisted: both describe what is being looked at
     *  right now, and a history that reopens filtered days later, with the reason
     *  forgotten, reads as a history that has lost entries. */
    int decisionFilter;
    boolean decisionsAllShown;

    /**
     * A tab switch while stillUnsafe(). The bar is absent during the whole commanded
     * stretch of a session (running / seal check / hold / assessment / validation), so the
     * only state that reaches here is a stop already sent and not yet evidenced — exactly
     * onBackPressed()'s UNEVIDENCED branch, worded identically. If a hold were somehow
     * outstanding (the bar should never be up then), refuse to navigate rather than walk
     * away from commanded pressure — the flow's own exits vent it.
     */
    private void promptGiveUp(final int dest) {
        if (Handoff.needsStop(running, sealChecking, session.heldKpa() != null,
                              assessing, validating || selfTesting)) {
            // When the pump IS reachable, the honest exit is the step's own STOP, which
            // vents and confirms — so send them to it.
            if (link.isReady()) {
                toast("Finish or stop the current step first");
                return;
            }
            // But when the link is DOWN, the app cannot stop or vent the pump from here at
            // all, so refusing only traps the user on a screen that can do nothing. Tell
            // them plainly and let them leave — the abort files the attempt and best-effort
            // stops (a no-op over a dead link), and they are warned to release it by hand.
            Ui.dress(this, Ui.dialog(this)
                .setTitle("The pump is not connected")
                .setMessage("This step was commanding the pump, but the link is down, so the "
                    + "app can't stop or vent it from here. If the pump may still be holding "
                    + "pressure, disconnect the tubing at the cuff.\n\nLeave this step?")
                .setPositiveButton("Leave", new DisconnectedLeave(dest))
                .setNegativeButton("Stay", null)
                .setCancelable(false)
                .show());
            return;
        }
        Ui.dress(this, Ui.dialog(this)
            .setTitle("The vent is not confirmed yet")
            .setMessage("A stop was sent, but the pump hasn't reported the pressure "
                + "falling, so it may still be holding. It is still being retried, and the "
                + "retries continue whether or not this screen is in front.\n\n"
                + "If this does not clear, disconnect the tubing at the cuff.")
            .setPositiveButton("Switch anyway", new TabLeaveUnconfirmed(dest))
            .setNegativeButton("Stay here", null)
            .setCancelable(false)
            .show());
    }

    /** Leave a commanded step whose pump the app can no longer reach (the link is down).
     *  Routes through the SAME abort the flow's own STOP uses — finishSession(true) files
     *  the attempt and best-effort sends a stop (harmless over a dead link) — then
     *  navigates, so the user is never trapped on a screen that can do nothing. */
    private final class DisconnectedLeave implements DialogInterface.OnClickListener {
        private final int dest;
        DisconnectedLeave(int d) { dest = d; }
        @Override public void onClick(DialogInterface d, int w) {
            log("=== left a commanded step with the link DOWN, at the user's choice ===");
            stopBecause(RunStopReason.WHY_STOP);
            if (running || sealChecking || assessing || validating) finishSession(true);
            else ventIfHeld("leave while disconnected");   // a held preview with no run
            goToDest(dest);
        }
    }

    /** Navigate to the tapped tab after the user chose to switch with the vent still
     *  unconfirmed. The watch is NOT cancelled — the retries are the only thing still
     *  trying, and this Activity keeps running them; only the screen changes. */
    private final class TabLeaveUnconfirmed implements DialogInterface.OnClickListener {
        private final int dest;
        TabLeaveUnconfirmed(int d) { dest = d; }
        @Override public void onClick(DialogInterface d, int w) {
            log("=== switched tab with the vent UNCONFIRMED, at the user's choice ===");
            goToDest(dest);
        }
    }

    /* ----------------------------------------------------------------- home */

    /**
     * Today, per proto/pump-console.html's #v-today / renderToday(): the streak, the
     * best, the week ring, the seven-day strip, the stat tiles, the starred routines and
     * one START.
     *
     * Every figure is derived from the sessions actually filed (Summary.of), never from
     * a running counter kept alongside them and never from a count multiplied by an
     * assumed constant — the prototype's TOTAL TIME was `sessions x 11 minutes`, so
     * halving every routine's length changed nothing on this screen (defect #06). The
     * streak is counted per DAY, so a second session on a day already counted does not
     * advance it (defect #04).
     */
    void showHome() {
        // THE DAY'S STEP IS WRITTEN DOWN, AND A WEEK AWAY ARMED, BEFORE THE PLAN CATCHES UP.
        // Both move the signature the sync compares; run after it (as they were), a first day
        // back left the routine at full pressure until the NEXT time Today was drawn - under a
        // card already saying the day runs 4 hg under, with START one tap away.
        long settleAt = System.currentTimeMillis();
        settleTaper(settleAt);
        armReturnReduction(settleAt);
        // The plan catches up before the screen is drawn, so a routine the plan has
        // superseded is never the one Today offers to run.
        syncPlanRoutines();
        body.removeAllViews();
        enterDest(Nav.SCR_TODAY);

        Model.Routine sel = model.routine(model.selected);
        if (sel == null && !model.routines.isEmpty()) {
            sel = model.routines.get(0);
            model.selected = sel.id;
        }
        offerPlanNotice();
        offerLevelUp();
        // t10 REAL-1: the due deload asks when it starts, once a morning.
        offerDeloadStart();

        long now = System.currentTimeMillis();
        // THE SCHEDULE goes in here, and everywhere else Stats is derived: the streak
        // counts SCHEDULED days now, so a Stats built without it silently reverts to the
        // all-days rule and Today would disagree with itself.
        // STAGE H TASK 5: deload days widen the same rest-day skip (TrainerTab.deloadDayRange
        // is {0,0} — a no-op — for every non-trainer user, so this is byte-identical to the
        // 3-arg call for the population this feature does not touch).
        long[] deloadDays = TrainerTab.deloadDayRange(model);
        Summary.Stats st = Summary.of(model.sessLog.all, now, model.sched,
            deloadDays[0], deloadDays[1]);
        int selPresets = sel == null ? 0 : model.plan(sel).size();

        /* THE PILL STRIP — day/training-status, streak and next-due, as three small
         * display pills above the screen's name. It replaces the greeting sentence that
         * used to lead here: the persistent header at the top of every screen already says
         * whether the pump is connected, and saying it twice on the one screen that is not
         * about the pump pushed everything that IS about the user below the fold. See
         * pillStrip() for the three pills themselves. */
        pillStrip(now, st);
        Ui.head(this, body, "Today");
        // T2 - the level's own numbers, explained where they are printed.

        // THE HERO — the selected routine and what START will do with it (duration, peak
        // target, stages). It leads the screen; the week ring and tiles get their own room
        // further down. Three states, each saying what to do next rather than leaving START
        // to fail later (the middle one — a routine that exists but plans no presets — is the
        // one that used to read "0:00 · 0 presets" above a live START and say nothing useful).
        // R8 - ABOVE the hero. It is about the session already begun today, and the hero
        // offers a fresh one; the older fact is the one that needs answering first.
        simBanner();
        // 7B: the plan-choice door rides the hero's kicker now (see heroRoutine).
        // A stored answer must not outlive the condition it was given for - growing into the
        // tube, or swapping to a narrower one, retires it before anything is drawn.
        if (model.syncOversizeAcceptance(girthNowCm())) Store.save(this, model);
        deloadAskCard(body, false);
        deloadDueCard(body, false);
        reductionCard();
        oversizeOfferCard();
        // F1 - ONE BLOCK, NOT THREE. The remainder card, the up-next card and the hero
        // were three answers to one question, stacked in an order you had to read to work
        // out. The ordering already picks a single winner; the screen shows a single winner,
        // and the other two are now the LEAD of this card rather than cards of their own.
        heroRoutine(sel, selPresets);

        // THE NEXT-DUE NUDGE now lives in the pill strip at the top of this screen (the
        // NEXT pill) rather than as its own line here — see pillStrip().

        // NEWLY-EARNED MILESTONES, shown once. Nothing here is earned by running the pump
        // deeper or longer; see Milestones.java.
        milestoneCard(now);

        // "READY TO PROGRESS?" (Stage E task 4, T1 A) — one card per routine that has
        // just cleared 5 clean sessions in a row and has not yet been offered ITS
        // streak's step-up. Placed beside milestoneCard (same shown-once, lime-accented
        // shape) rather than folded into it: see Progression.java's own class doc for
        // why this lives in its own file, deliberately apart from Milestones.java.
        stepUpCard();

        // THE SETUP CHECKLIST used to render here as an inline card (Stage D task 1,
        // dist/round5-options.html #n1 decision "C — GUIDED CHECKLIST CARD"). Task 3, Stage G
        // moved it to a floating popup shown once per cold start instead — a card that could
        // reappear on every single visit to Today for as long as any step was outstanding
        // was the thing users actually complained about. See onCreate's openInitial Runnable
        // for where it is now raised, and showSetupPopup()'s own doc for the full reasoning.
        // Nothing else about the checklist's STATE changed: setupDone/setupDismissed are the
        // same fields, latched the same way.

        // THE ACTION TRIO. Start a session, run one cycle without a routine, log a reading,
        // pick a favourite: the four things this app is FOR. They were a green primary
        // followed by two flat rows indistinguishable from every other flat row on the
        // screen, so two of the app's three front doors read as list items. They are now
        // one group, set apart from the page by their own container, and each carries a
        // glyph so it is findable by shape as well as by reading. Favourites (Stage B task
        // 7) joined the group as its 4th member, opening a sheet rather than navigating —
        // see the "TRIO'S 4TH SLOT" comment below.
        //
        // ONLY START IS GREEN, and that is now a rule rather than an exception: see
        // Look#SAFE's own second sanctioned use, "the affirmative primary action of a
        // screen, of which there is at most one". This is that one. The hierarchy is real —
        // START is what most days need. The other three take the group's shared treatment
        // (surface-high fill, an accent edge, a heavier label) which reads as "an action"
        // without claiming to be the primary and without borrowing a state colour. NO
        // AMBER: none of the four commands the pump at the moment it is tapped, and amber
        // is only ever the pump under command.
        LinearLayout actions = Ui.col(this);
        actions.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
        Ui.lift(this, actions, Ui.ELEV_CARD);
        actions.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12));

        // 7B: START moved INTO the hero card — this block keeps only the three
        // non-primary doors (confirmStart() still answers every state with a reason).
        Button manual = actionButton(actions, "◆", "MANUAL RUN",
            "One cycle, no routine", Ui.SURFHI);
        manual.setContentDescription("Manual run, a one-off cycle with no routine");
        manual.setOnClickListener(new OpenManualTap());

        Button logReading = actionButton(actions, "✎", "LOG A READING",
            "A measurement on its own", Ui.SURFHI);
        logReading.setContentDescription("Log a reading, on its own with no routine or session");
        logReading.setOnClickListener(new OpenLogReadingTap(Nav.TODAY));

        // THE TRIO'S 4TH SLOT (Stage B task 7), per the locked visual reference
        // (dist/final-design.html section 1/TODAY): MANUAL/LOG/FAVS. Favourites used to be
        // its own scrolling section further down the page (Ui.sectionHead("Favourites") plus
        // a row per starred routine); it now opens as a bottom sheet instead — see
        // openFavourites() for the sheet and favouriteRow() for the row rendering, which is
        // the exact logic that section used to run inline, extracted so there is one copy.
        Button favs = actionButton(actions, "★", "FAVOURITES",
            "Pick a starred routine", Ui.SURFHI);
        favs.setContentDescription("Favourites, pick from your starred routines");
        favs.setOnClickListener(new OpenFavouritesTap());

        LinearLayout.LayoutParams actLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        actLp.topMargin = Ui.dp(this, 2); actLp.bottomMargin = Ui.dp(this, 12);
        body.addView(actions, actLp);

        // THE WEEK, AND THE ACHIEVEMENT GAUGE — one combined panel per the locked visual
        // reference (dist/final-design.html section 1/TODAY): the G1 ring (how many of
        // Milestones.CATEGORY_TOTAL categories are earned), the streak/rest-day/next-badge
        // KV stack, and — unchanged — the same 7-day StreakRing this screen has always
        // drawn. Replaces the formerly separate streak card (which used to lead the whole
        // screen) and the "This week" insight card (which used to sit below Favourites);
        // see weekAchievementsCard() for why they are now one panel and where in this
        // method's history each used to live.
        weekAchievementsCard(st, now);

        // WHAT HAPPENED LAST TIME, and the latest thing earned. Both are things the user
        // would otherwise go hunting for, and both are one tap from where they lead.
        lastSessionCard();
        // AFTER the session card, because a session is what Today is for and retention is
        // the thing you do between them - and absent entirely unless it was asked for.
        retentionCard();

        // Favourites (Stage B task 7): moved off Today's face into the FAVS sheet — see
        // the action trio above and openFavourites()/favouriteRow() for where this content
        // and its row rendering live now.

        // The two safety facts worth carrying on the face, as one line plus a ⓘ. Link
        // exclusivity and the raw log path used to sit here too; they are developer/
        // diagnostic detail and now live only in Settings, where they belong — a home
        // screen is not a log viewer.
        todayPlanState();
        todaySafetyLine();

        // The considered entrance: cascade the first sections in on arrival only, built on the
        // same animateBodyIn/Look.staggerDelay machinery and honouring the system scale.
        staggerBodyIn();
    }

    /* ------------------------------------------------- Today · schedule & progress */

    /**
     * THE PILL STRIP — day/training-status, streak and next-due as three small display
     * pills at the very top of Today, per dist/final-design.html section 1/TODAY:
     * {@code <span class="pill pa">TUE·TRAIN</span><span class="pill pl">STRK 01</span>
     * <span class="pill pd">NEXT 19:00</span>}. They replace the greeting sentence and the
     * next-due nudge that used to carry these same three facts as plain text below the
     * hero panel; nothing here is a new figure — each pill quotes a value this screen
     * already derives, and the streak also gets its full, richer telling again in
     * weekAchievementsCard() further down.
     *
     * INFORMATIONAL ONLY. None of the three is a control, so none carries a click listener
     * or a selection state — this borrows periodRow()'s lime-wash / SURFHI+DIM fill+ink
     * pairing for a row nothing here can tap (see addPill()).
     *
     * COLOUR. The day pill is TEXT (bright) on a training day and DIM on a rest day —
     * NOT amber (fixed in Task 13's colour-discipline sweep: an earlier version wore
     * amber here, which this very file's own hero-card doc argues against two ways —
     * "a selected routine is a PLAN, not the pump under command", and "today is scheduled
     * to train" is exactly that same kind of plan fact, not a claim that the pump is
     * under command right now). Bright-vs-dim is the SAME "the colour is only emphasis"
     * pairing the Library screen's ★ favourite toggle already uses for the identical
     * reason — without borrowing amber OR reaching for the lime the ● select marker wears.
     * The streak pill is LIME once the streak is above zero — the same "earned, not
     * neutral" rule weekAchievementsCard's own ring follows — and DIM at zero. The
     * next-due pill is always DIM: it names a clock time, not a state to celebrate.
     */
    private void pillStrip(long now, Summary.Stats st) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);

        boolean training = model.sched != null && model.sched.isTodayTraining(now);
        addPill(row, greetingLine(now),
            Ui.SURFHI, training ? Ui.TEXT : Ui.DIM, 0);

        // POLISH #10: the word every other surface uses, and no leading zero — "STRK 00"
        // was the app's one abbreviation, and a machine-padded one at that. "NEXT RUN"
        // says next WHAT.
        String streakText = "STREAK " + st.streak;
        addPill(row, streakText,
            st.streak > 0 ? Ui.ACCENT_DIM : Ui.SURFHI, st.streak > 0 ? Ui.ACCENT : Ui.DIM,
            Look.S1);

        // The clock figure Schedule#nextDueLine itself quotes for its "at 19:00" clause —
        // reused here directly rather than parsed back out of that sentence.
        String nextText = "NEXT RUN " + (model.sched != null ? model.sched.hhmm() : "--:--");
        addPill(row, nextText, Ui.SURFHI, Ui.DIM, Look.S1);

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.topMargin = Ui.dp(this, 10);
        body.addView(row, lp);
    }

    /** One pill in pillStrip() — Ui.microLabel at Look.R_PILL/Look.SP_MICRO, the same
     *  fill+ink pairing periodRow()'s selected/unselected buttons wear, minus the
     *  selection-state click wiring nothing in this row needs. Sized to its own text
     *  rather than forced equal-width: three pills side by side, not a full-width
     *  picker. */
    private void addPill(LinearLayout row, String text, int fill, int ink, int leftMarginDp) {
        TextView pill = Ui.microLabel(this, null, text, ink);
        pill.setBackground(Ui.roundRect(this, fill, Look.R_PILL));
        pill.setPadding(Ui.dp(this, Look.S3), Ui.dp(this, 2), Ui.dp(this, Look.S3), Ui.dp(this, 2));
        pill.setTypeface(pill.getTypeface(), android.graphics.Typeface.BOLD);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        if (leftMarginDp > 0) lp.leftMargin = Ui.dp(this, leftMarginDp);
        row.addView(pill, lp);
    }

    /**
     * The one-time milestone card. Shows only what is NEWLY earned — the ids already shown
     * are persisted on the model — and marks them seen as it draws, so it appears once and
     * then never again for the same milestone.
     *
     * Marking them seen HERE, at the moment they are drawn, rather than behind a dismiss
     * button: a card the user has to dismiss to be rid of is a card that reappears if they
     * navigate away, which for a "congratulations" is worse than showing it once.
     */
    private void milestoneCard(long now) {
        List<Milestones.Earned> fresh = Milestones.newlyEarned(
            model.sessLog.all, model.sched, now, model.seenMilestones);
        if (fresh.isEmpty()) return;

        // A PLAIN CARD. It wore a lime left edge; coloured edges are kept for warnings and
        // faults only (owner's pick, polish item 3), and a milestone is neither. The lime
        // MILESTONE label still says it is something the user DID.
        LinearLayout h = new LinearLayout(this);
        h.setOrientation(LinearLayout.HORIZONTAL);
        h.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
        Ui.lift(this, h, Ui.ELEV_CARD);
        h.setPadding(Ui.dp(this, 16), Ui.dp(this, 12), Ui.dp(this, 16), Ui.dp(this, 12));

        LinearLayout card = Ui.col(this);
        h.addView(card, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        TextView head = new TextView(this);
        head.setText(fresh.size() == 1 ? "MILESTONE" : "MILESTONES");
        head.setTextColor(Ui.ACCENT);
        head.setTextSize(Look.SP_LABEL);
        if (android.os.Build.VERSION.SDK_INT >= 21)
            head.setLetterSpacing(Look.LABEL_TRACKING_EM);
        card.addView(head);

        StringBuilder said = new StringBuilder();
        for (int i = 0; i < fresh.size(); i++) {
            Milestones.Earned e = fresh.get(i);
            TextView t = new TextView(this);
            t.setText(e.title);
            t.setTextColor(Ui.TEXT);
            t.setTextSize(Look.SP_HEADING);
            t.setPadding(0, Ui.dp(this, 6), 0, 0);
            card.addView(t);
            TextView d = new TextView(this);
            d.setText(e.detail);
            d.setTextColor(Ui.DIM);
            d.setTextSize(Look.SP_CAPTION);
            d.setPadding(0, Ui.dp(this, 2), 0, 0);
            card.addView(d);
            if (said.length() > 0) said.append(". ");
            said.append(e.title).append(". ").append(e.detail);
            if (!model.seenMilestones.contains(e.id)) model.seenMilestones.add(e.id);
        }
        Ui.group(h, "Milestone. " + said);

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.bottomMargin = Ui.dp(this, 12);
        body.addView(h, lp);

        // Persist immediately: the card has now been on screen, and a kill before the next
        // save would otherwise show it again.
        Store.save(this, model);
    }

    /**
     * "READY TO PROGRESS?" (Stage E task 4, T1 A, dist/round7-options.html's decisions
     * list — "after 5 clean ≥95% completions, one-tap suggested step-up (creates a
     * copy)"). Same OUTER shape {@link #milestoneCard}/{@link #goalReachedCard} already
     * draw for a one-time-per-moment card: a lime label (this is the "progress, streak"
     * meaning {@link Look#ACCENT}'s own doc names, not a milestone badge — see {@link
     * Progression}'s own class doc for why the trigger this card acts on lives in its
     * own file rather than inside {@link Milestones}), the surface colour, elevated, no
     * coloured edge (those are for warnings and faults, polish item 3), marked SHOWN the
     * moment it draws so a kill before the next save cannot make it reappear.
     *
     * ONE CARD PER QUALIFYING, NOT-YET-SHOWN ROUTINE STREAK — {@link
     * Progression#cleanStreak} against {@link Progression#STEP_UP_STREAK_LEN}, keyed by
     * {@link Model#stepUpKey} against {@link Model#stepUpShown} — the same "recompute
     * fresh, diff against shown" shape {@link #goalReachedCard} already uses rather than
     * catching the transition at one specific session-filing call site. Routine-agnostic
     * on purpose: this walks every routine in {@link Model#routines}, not only the one
     * {@link #heroRoutine} currently has selected, because a streak on a routine that
     * simply is not selected right now is no less real.
     *
     * THE ACTION CHIP creates the step-up copy immediately (no confirm dialog — a copy
     * is non-destructive, exactly the same reasoning {@link DupRoutineTap} already
     * relies on for its own un-confirmed "Duplicate") and opens it in the routine
     * editor, mirroring {@link DupRoutineTap}'s own post-copy navigation, so the user
     * lands somewhere they can see and adjust the exact numbers before ever running it.
     * There is no separate "not now" control: not tapping IS the decline, and the same
     * shown-once mark means this exact streak is never offered again — a fresh offer
     * only comes from a fresh streak (a break, then five more clean runs), per the
     * task's own spec.
     */
    private void stepUpCard() {
        boolean any = false;
        for (int i = 0; i < model.routines.size(); i++) {
            Model.Routine r = model.routines.get(i);
            if (r == null || r.id == null || r.id.length() == 0) continue;
            // S19 (owner ruling, 2026-09-26) - THE TRAINER ALREADY GOVERNS THIS ROUTINE'S
            // PULL, on its own ladder (level, yield, deload). This card's own fixed nudge
            // is a second, uncoordinated progression path over the same pressure, so a
            // routine still carrying a track gets no offer here.
            if (!Progression.eligibleForStepUp(r)) continue;
            int streak = Progression.cleanStreak(model.sessLog.all, r.id);
            if (streak < Progression.STEP_UP_STREAK_LEN) continue;
            long start = Progression.cleanStreakStartTs(model.sessLog.all, r.id);
            String key = Model.stepUpKey(r.id, start);
            if (model.stepUpShown.contains(key)) continue;
            any = true;

            // A PLAIN CARD, like milestoneCard's: no coloured edge, since an offer to step
            // up is not a warning or a fault (polish item 3). The lime label carries it.
            LinearLayout h = new LinearLayout(this);
            h.setOrientation(LinearLayout.HORIZONTAL);
            h.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
            Ui.lift(this, h, Ui.ELEV_CARD);
            h.setPadding(Ui.dp(this, 16), Ui.dp(this, 12), Ui.dp(this, 16), Ui.dp(this, 12));

            LinearLayout card = Ui.col(this);
            h.addView(card, new LinearLayout.LayoutParams(0,
                    ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

            TextView head = new TextView(this);
            head.setText("READY TO PROGRESS?");
            head.setTextColor(Ui.ACCENT);
            head.setTextSize(Look.SP_LABEL);
            if (android.os.Build.VERSION.SDK_INT >= 21)
                head.setLetterSpacing(Look.LABEL_TRACKING_EM);
            card.addView(head);

            String routName = r.name == null || r.name.length() == 0 ? "This routine" : r.name;
            TextView t = new TextView(this);
            t.setText(routName);
            t.setTextColor(Ui.TEXT);
            t.setTextSize(Look.SP_HEADING);
            t.setPadding(0, Ui.dp(this, 6), 0, 0);
            card.addView(t);

            TextView d = new TextView(this);
            d.setText(Progression.STEP_UP_STREAK_LEN + " clean runs in a row, "
                + Math.round(Progression.STEP_UP_MIN_RATIO * 100) + "%+ each time — "
                + "a copy with the pull pressure nudged up is ready to review.");
            d.setTextColor(Ui.DIM);
            d.setTextSize(Look.SP_CAPTION);
            d.setPadding(0, Ui.dp(this, 2), 0, Ui.dp(this, 6));
            card.addView(d);

            Button chip = Ui.flat(this, card, "Create the step-up copy ›");
            chip.setTextColor(Ui.ACCENT);
            chip.setOnClickListener(new StepUpTap(r.id));

            Ui.group(h, "Ready to progress. " + routName + ", " + Progression.STEP_UP_STREAK_LEN
                + " clean runs in a row. Create a stepped-up copy to review.");

            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            lp.bottomMargin = Ui.dp(this, 12);
            body.addView(h, lp);

            model.stepUpShown.add(key);
        }
        // Persist immediately, the same "the card has now been on screen" reasoning
        // milestoneCard()/goalReachedCard() already state for their own save.
        if (any) Store.save(this, model);
    }

    /** {@link #stepUpCard}'s one-tap action — creates the stepped-up copy (Model.Routine
     *  #stepUpCopy) and opens it in the routine editor, mirroring {@link DupRoutineTap}'s
     *  own post-copy navigation exactly. A missing routine (deleted between the card's
     *  draw and the tap) falls back to Today rather than crashing on a null. */
    private final class StepUpTap implements View.OnClickListener {
        private final String routineId;
        StepUpTap(String routineId) { this.routineId = routineId; }
        @Override public void onClick(View v) {
            Model.Routine r = model.routine(routineId);
            if (r == null) { showHome(); return; }
            String id = model.newRoutineId();
            model.routines.add(r.stepUpCopy(id, model));
            editStageIdx = 0;
            Store.save(SessionActivity.this, model);
            Ui.snack(SessionActivity.this, rootFrame, "Step-up copy created");
            showRoutEdit(id);
        }
    }

    /**
     * THE SETUP CHECKLIST (Stage D task 1, the LOCKED dist/round5-options.html #n1 mock,
     * lines 65-70 — "Get set up"). Task 3, Stage G changed the PRESENTATION from an inline
     * Today card to a floating popup shown once per cold start (see onCreate's openInitial
     * Runnable) — nothing about the STEPS, their signals, or their latching changed; {@link
     * #setupSignals} below is the exact per-step live-check-with-latch logic the old inline
     * card used, unchanged, now shared by every place that needs a fresh read.
     *
     * THE FIRST THREE ROWS ARE THE MOCK'S OWN, VERBATIM: "Connect your pump" / "Run the
     * starter routine" / "Log a baseline measurement". At the time those words were
     * locked, this doc also said "no fourth concept (a goal, a Templates picker) belongs
     * here" — and that still holds for THAT kind of fourth row: a goal or a Templates
     * picker is a Progress/Settings feature, and N1 is not the door to either.
     *
     * ROW 4 ("Turn off battery optimisation") is a deliberate, later exception to that
     * same sentence, not a quiet reversal of it. Stage E task 3 (T18,
     * dist/round7-options.html — "guided exemption in setup + pre-run check;
     * service-killed detection re-offers") is a safety feature, not a product-scope
     * addition, and that task's own Global Constraints direct it to hook into whatever
     * first-run checklist already exists rather than build a second, parallel one-time
     * flow the user would have to see twice. See {@link #openBatteryExemptionSettings}
     * for the flow the row's tap opens and {@link Model#SETUP_BATTERY}'s own doc for the
     * identical reasoning stated from the model side.
     *
     * ROW 2 actually starts the seeded Starter Routine — {@link StartStarterRoutineTap}
     * selects {@link Model#SEED_STARTER_ROUTINE_ID} before calling {@link #confirmStart},
     * so the tap does what the label promises. Its DONE signal stays deliberately
     * loose, though: "a session exists" ({@link Model#sessLog}), not "the starter routine
     * specifically was run". A user who skips the row and runs their own routine first has
     * still done the thing this step exists to get them to do, and a checklist that
     * refuses to check off a step the user has functionally completed is a nag, not a
     * guide.
     *
     * ROW 3 reuses the exact door N3's "Log measurement" shortcut and Today's own
     * "LOG A READING" action use ({@link OpenLogReadingTap}) rather than inventing a
     * second path to the same screen. Its DONE signal is {@link Model#measLog} being
     * non-empty — the same log {@link OpenLogReadingTap} writes into.
     *
     * ROW 1 is the pump-connected signal ({@link #lastStateConnected}), unchanged.
     *
     * Per Round 6 decision S1 B ("first-run seed only") the library is silently
     * pre-populated with one beginner Starter Routine on first run (see {@link
     * Model#seed}) — there is no Templates section and no picker.
     *
     * LATCHED, not live-recomputed on every draw: {@link Model#setupDone} records a step
     * the moment its signal first reads true and never drops it, so disconnecting the pump
     * or deleting history/readings later does not un-check a step the user already
     * cleared — the same "shown once, stays true" contract {@link Model#seenMilestones}
     * keeps for milestones. The popup auto-closes once every step has latched true
     * ({@link Model#setupAllDone}), and stays permanently closed once "Dismiss" is tapped
     * (regardless of what is still outstanding) — same rule the old card's × enforced. Row 4
     * follows the exact same live-check-with-latch shape row 1 already does
     * ({@code isBatteryExempt() || setupDone.contains(...)}) rather than a bare latch: if
     * the OS or the user later revokes the exemption, THIS popup is not where that gets
     * caught again (a first-run nudge that resurfaces forever is a nag) — the live,
     * never-latched pre-run check in {@link #confirmStart}/{@link #confirmManualRun} and
     * the kill-detection in {@link #onResume} are what stay current for as long as the
     * app is used, which is the split {@link Session#killedMidRun}'s own doc assumes.
     *
     * DISMISSAL HAS TWO DELIBERATELY DIFFERENT WEIGHTS. The "Dismiss" button (the dialog's
     * negative button, {@link DismissSetupTap}) is the old ×: permanent, sets {@link
     * Model#setupDismissed}. A back press or a scrim tap (setCancelable(true)) is SOFTER —
     * nothing is persisted, so the popup is simply not showing right now and returns on the
     * next cold start, "not now" rather than "never ask again". Tapping any of rows 1-3
     * closes the popup the same soft way (see {@link PopupNavTap}) before running that row's
     * own navigation — the popup floats OVER whatever screen is behind it, and every one of
     * those three rows navigates the Activity underneath, so leaving it up would mean a
     * "Start X?" confirm or the log-reading screen renders BEHIND this popup's scrim. Row 4
     * is the one exception: it leaves the app for a system Settings screen, so the popup is
     * left showing and is refreshed instead on the way back — see {@link
     * #refreshSetupPopup}'s own doc.
     *
     * MODAL-COLLISION SEQUENCING (Task 3's own investigation mapped every modal that can
     * fire around app start): this popup is raised from INSIDE onCreate's openInitial
     * Runnable, which only ever runs once the whole-app lock gate has stood down (or was
     * never engaged) — see onCreate's own 40-line safety-trace doc — which structurally
     * rules out landing on top of or under the biometric/PIN challenge. It is POSTED via the
     * existing `ui` Handler rather than shown synchronously, so onResume — and therefore the
     * kill-detected dialog it can raise — runs first; showSetupPopup() then checks {@link
     * #killDialog}'s own isShowing() before doing anything, so a genuine mid-run kill always
     * wins and the popup simply does not appear THAT launch (nothing is persisted — a normal
     * cold start after that one still shows it if it is still owed). A static-shortcut
     * launch (EXTRA_SHORTCUT) is detected and skipped entirely: the user asked for one
     * specific action, and a checklist popup on top of it is an interruption, not a help.
     * {@link #onUnknownPump} dismisses this popup (the soft way) before showing its own "New
     * pump found" dialog, for the same reason rows 1-3 do. showSetupPopup() also checks
     * {@link #stillUnsafe} and {@link RunService#isRunning}, even though the first is a
     * compile-time-constant false during onCreate (see onCreate's own doc for why
     * RunService.isRunning() is the term that actually matters at COLD open) — it becomes
     * meaningful the moment {@link #refreshSetupPopup} calls back into this same gate from a
     * WARM resume, where stillUnsafe() is no longer constant.
     */
    private AlertDialog setupPopup;

    private void showSetupPopup() {
        if (isFinishing()) return;
        if (model.setupDismissed) return;
        if (setupPopup != null && setupPopup.isShowing()) return;
        if (killDialog != null && killDialog.isShowing()) return;
        if (RunService.isRunning() || stillUnsafe()) return;
        /* AND NOT OVER THE "YOUR DATA COULD NOT BE READ" DIALOG.
         *
         * warnStoreUnreadable is deliberately raised first, "ahead of every other popup" -
         * and this one is POSTED 600 ms later, so it landed on top of it anyway. Seen on the
         * emulator: a corrupt store showed the setup checklist, and the sentence explaining
         * why the app looked empty was underneath it. A checklist for setting up a fresh
         * install is exactly the wrong thing to show somebody whose library is missing. */
        if (Store.storeWasUnreadable()) return;

        boolean[] s = setupSignals();
        if (Model.setupAllDone(s[0], s[1], s[2], s[3], s[4])) return;

        LinearLayout col = Ui.col(this);
        col.setPadding(Ui.dp(this, 16), Ui.dp(this, 14), Ui.dp(this, 16), Ui.dp(this, 10));
        setupRow(col, "Connect your pump", s[0], new PopupNavTap(new OpenConnectTap()));
        setupRow(col, "Run the starter routine", s[1], new PopupNavTap(new StartStarterRoutineTap()));
        setupRow(col, "Log a baseline measurement", s[2],
            new PopupNavTap(new OpenLogReadingTap(Nav.TODAY)));
        // AFTER THE MEASUREMENT, because everything the rack derives is read against a
        // measured girth: the fit band, the percentage over girth, the reduction it offers.
        // Ordered here rather than earlier so the row is reached with that number already in
        // hand, which is the order trainer-v3 Phase 1 asks for. It stays skippable like every
        // other row - an empty rack is exactly today's behaviour everywhere.
        setupRow(col, "Describe your cylinder", s[3], new PopupNavTap(new OpenCylinderRackTap()));
        setupRow(col, "Turn off battery optimisation", s[4], new OpenBatteryExemptionTap());
        /* polish F1: ONE DOOR INTO THE TRAINER SETUP. The checklist and the Trainer's own
         * "Get started" both asked for the first plan; the checklist only dismissed. This row
         * opens the setup (or, once enrolled, the Trainer as it stands - never a fresh setup
         * over a plan in progress, FirstRun#finishAction's rule). It is a door, not one of the
         * five the checklist counts: done or not, it changes when the popup stops showing. */
        setupRow(col, "Set up the trainer", model.trainerEnrolled,
            new PopupNavTap(new SetUpTrainerTap()));

        ScrollView sc = new ScrollView(this);
        if (android.os.Build.VERSION.SDK_INT >= 29) sc.setEdgeEffectColor(Look.ACCENT);
        sc.addView(col);

        setupPopup = Ui.dialog(this)
            .setTitle("Get set up")
            .setView(sc)
            .setNegativeButton("Dismiss", new DismissSetupTap())
            .setCancelable(true)
            .setOnDismissListener(new SetupPopupDismissListener())
            .show();
        Ui.dress(this, setupPopup);
    }

    /** Closes the popup WITHOUT touching {@link Model#setupDismissed} — the "soft" close
     *  every row's navigation and {@link #onUnknownPump} use, as opposed to {@link
     *  DismissSetupTap}'s permanent one. Safe to call whether or not the popup is currently
     *  showing. */
    private void dismissSetupPopup() {
        if (setupPopup == null) return;
        try { setupPopup.dismiss(); } catch (Exception ignored) { }
        setupPopup = null;
    }

    /** The 3c fix: re-reads every step's live signal and rebuilds the popup — called from
     *  {@link #onResume} (covers row 4, the reported bug: returning from the system battery-
     *  exemption screen) and from {@link #onState}'s rising edge (covers row 1, the same
     *  staleness bug on the connect signal — present but never reported; see onState's own
     *  call site). Rows 2 and 3 need no such hook: their signals can only change from a
     *  screen that owns the display, which is gone by the time this popup could next show,
     *  so this single hook is still "the general case", not a fourth special case bolted on.
     *  A no-op unless the popup is ACTUALLY showing right now — this is a refresh, never a
     *  way to summon a dismissed or not-yet-due popup back onto the screen.
     *  Dismiss-then-reshow rather than mutating the live dialog's content view: simpler, and
     *  it reuses showSetupPopup()'s own all-done check, so the one case where the very step
     *  that just changed was the LAST outstanding one closes the popup for good instead of
     *  leaving an empty shell up — strictly better than the old card's stale dot ever
     *  offered. */
    private void refreshSetupPopup() {
        if (setupPopup == null || !setupPopup.isShowing()) return;
        dismissSetupPopup();
        showSetupPopup();
    }

    /** Wraps another row's tap listener so the popup closes (softly — see the class doc on
     *  {@link #showSetupPopup}) BEFORE that listener runs. Every one of rows 1-3 navigates
     *  the Activity underneath this popup; without this wrapper the popup would still be
     *  floating over whatever screen — or dialog — that navigation opens. Row 4 does NOT use
     *  this wrapper: it leaves the app entirely, and the popup is meant to still be there
     *  (refreshed) when the user comes back. */
    /** The checklist's trainer row (polish F1): the same road the first-run setup's end
     *  takes - the setup for a new plan, the Trainer for one already running. */
    private final class SetUpTrainerTap implements View.OnClickListener {
        @Override public void onClick(View v) {
            if (model.trainerEnrolled) { showTrainer(); return; }
            trainerOnboardMarks = model.marksEasily;
            startTrainerOnboard(false);
        }
    }

    private final class PopupNavTap implements View.OnClickListener {
        private final View.OnClickListener inner;
        PopupNavTap(View.OnClickListener inner) { this.inner = inner; }
        @Override public void onClick(View v) {
            dismissSetupPopup();
            inner.onClick(v);
        }
    }

    /** Nulls {@link #setupPopup} however the dialog went away — the "Dismiss" button (which
     *  {@link DismissSetupTap} also persists), a back press, or a scrim tap all end up here,
     *  which is the one place that has to run for every path, unlike {@link
     *  #dismissSetupPopup}'s own null-out, which only covers the paths that call it
     *  directly (row taps, a refresh).
     *
     *  THE IDENTITY CHECK IS LOAD-BEARING, not defensive belt-and-braces: Dialog.dismiss()
     *  does NOT fire this listener synchronously — it posts the DISMISS message for a later
     *  Looper pass. {@link #refreshSetupPopup} dismisses the OLD dialog and then immediately
     *  creates and assigns a NEW one to {@link #setupPopup} before that posted message is
     *  drained. Without the {@code d == setupPopup} guard, the old dialog's deferred
     *  onDismiss would fire after the reassignment and null out the reference to the dialog
     *  that is now actually on screen — a stale null that defeats every soft-dismiss caller
     *  ({@link PopupNavTap}, {@link #onUnknownPump}) and 3b's whole no-stacking guarantee,
     *  since {@link #dismissSetupPopup} silently no-ops on a null field. Each dialog instance
     *  is only ever allowed to null the reference that is CURRENTLY pointing at IT. */
    private final class SetupPopupDismissListener implements DialogInterface.OnDismissListener {
        @Override public void onDismiss(DialogInterface d) {
            if (d == setupPopup) setupPopup = null;
        }
    }

    /** Posted from onCreate's openInitial Runnable — see that Runnable's own comment for why
     *  this is POSTED rather than shown synchronously, and why a static-shortcut cold open
     *  never schedules this at all. */
    private final class ShowSetupPopupRunnable implements Runnable {
        @Override public void run() { showSetupPopup(); }
    }

    /**
     * S16 FOLLOW-UP (the owner's decision, 2026-09-26): THE ONE QUESTION AFTER THE UPDATE.
     *
     * 0.10 made training days only the feeder's default for every file, so a trainer who had
     * been offered the feeder on rest days is asked, once, which they want - in words that
     * name both readings of the guidance - and the answer sets the "Feeder on rest days too" switch
     * ({@link Model#answerFeederDays}, saved at once). Whether it is owed is the model's
     * ({@link Model#feederDaysAskDue}): only a file saved before the switch existed, whose plan
     * has the feeder in it. A new install is never asked.
     *
     * THE SETUP POPUP'S GUARDS, AND ONE MORE. Posted from the same cold open, after it, and
     * never over it: not while a run or a hold is live or the kill-detected dialog is up, not
     * over the "your data could not be read" dialog, and not on top of the checklist. A launch
     * that cannot ask leaves it owed; so does closing it with Back - it is asked until it is
     * answered, and once answered never again. Words only: nothing is commanded.
     */
    private AlertDialog feederDaysAsk;

    private void showFeederDaysAsk() {
        if (isFinishing()) return;
        if (!model.feederDaysAskDue()) return;
        // t10 R-09 (A6): the feeder follows the girth session now and the rest-days switch is
        // read as off (TrainerTab#feederRestDaysOn), so the question has nothing left to set.
        if (!TrainerTab.feederRestDaysOn(model)) return;
        if (feederDaysAsk != null && feederDaysAsk.isShowing()) return;
        if (killDialog != null && killDialog.isShowing()) return;
        if (setupPopup != null && setupPopup.isShowing()) return;
        if (RunService.isRunning() || stillUnsafe()) return;
        if (Store.storeWasUnreadable()) return;
        feederDaysAsk = Ui.dialog(this)
            .setTitle(TrainerTab.FEEDER_DAYS_ASK_TITLE)
            .setMessage(TrainerTab.FEEDER_DAYS_ASK_TEXT)
            .setPositiveButton("Training days only", new FeederDaysAnswerTap(false))
            .setNegativeButton("Rest days too", new FeederDaysAnswerTap(true))
            .setCancelable(true)
            .show();
        Ui.dress(this, feederDaysAsk);
    }

    /** Closes the question WITHOUT answering it - it stays owed (see {@link #showFeederDaysAsk}). */
    private void dismissFeederDaysAsk() {
        if (feederDaysAsk == null) return;
        try { feederDaysAsk.dismiss(); } catch (Exception ignored) { }
        feederDaysAsk = null;
    }

    /** The answer: sets the switch, settles the question, and saves both at once. */
    private final class FeederDaysAnswerTap implements DialogInterface.OnClickListener {
        private final boolean restDays;
        FeederDaysAnswerTap(boolean r) { restDays = r; }
        @Override public void onClick(DialogInterface d, int w) {
            model.answerFeederDays(restDays);
            Store.save(SessionActivity.this, model);
            feederDaysAsk = null;
            if (currentScreen == Nav.SCR_TRAINER) showTrainer();
        }
    }

    private final class ShowFeederDaysAskRunnable implements Runnable {
        @Override public void run() { showFeederDaysAsk(); }
    }

    /** Computes the four checklist steps' live-or-latched DONE state and latches any that
     *  just turned true into {@link Model#setupDone} (persisted immediately if anything
     *  changed) — the exact live-check-with-latch shape the old inline card used, pulled out
     *  here so {@link #showSetupPopup} and {@link #refreshSetupPopup} share one
     *  implementation rather than two copies that could drift. Order — connect, session,
     *  measurement, cylinder, battery — matches the popup's row order and {@link
     *  Model#setupAllDone}'s parameter order. */
    private boolean[] setupSignals() {
        boolean connectDone     = lastStateConnected || model.setupDone.contains(Model.SETUP_CONNECT);
        boolean sessionDone     = !model.sessLog.all.isEmpty() || model.setupDone.contains(Model.SETUP_SESSION);
        boolean measurementDone = !model.measLog.all.isEmpty() || model.setupDone.contains(Model.SETUP_MEASUREMENT);
        // A DESCRIBED CYLINDER, not an ACTIVE one: the rack having any entry is what the app
        // needed - it can then scale a standardised photo, name the tube on the pre-run screen
        // and derive a fit. Latched like the rest, so emptying the rack later cannot flick a
        // finished step back to unchecked.
        boolean cylinderDone    = !model.cylinders.isEmpty() || model.setupDone.contains(Model.SETUP_CYLINDER);
        boolean batteryDone     = isBatteryExempt() || model.setupDone.contains(Model.SETUP_BATTERY);

        boolean changed = false;
        if (connectDone && !model.setupDone.contains(Model.SETUP_CONNECT)) {
            model.setupDone.add(Model.SETUP_CONNECT); changed = true;
        }
        if (sessionDone && !model.setupDone.contains(Model.SETUP_SESSION)) {
            model.setupDone.add(Model.SETUP_SESSION); changed = true;
        }
        if (measurementDone && !model.setupDone.contains(Model.SETUP_MEASUREMENT)) {
            model.setupDone.add(Model.SETUP_MEASUREMENT); changed = true;
        }
        if (cylinderDone && !model.setupDone.contains(Model.SETUP_CYLINDER)) {
            model.setupDone.add(Model.SETUP_CYLINDER); changed = true;
        }
        if (batteryDone && !model.setupDone.contains(Model.SETUP_BATTERY)) {
            model.setupDone.add(Model.SETUP_BATTERY); changed = true;
        }
        if (changed) Store.save(this, model);

        return new boolean[] { connectDone, sessionDone, measurementDone, cylinderDone,
                               batteryDone };
    }

    /** One row of {@link #showSetupPopup}: a leading dot (filled GOOD when done, a
     *  hollow FAINT ring otherwise — {@link Look#TICK_DOT_DP}, the same 7dp mark the
     *  consistency strip already draws dots at), the step's label, and a trailing "✓" tag
     *  once done. Deep-links to the screen that step is done FROM, tapped or not — the
     *  round5 mock's own words for the card ("each step deep-links to the right screen"). */
    private void setupRow(LinearLayout card, String label, boolean done, View.OnClickListener tap) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(0, Ui.dp(this, 7), 0, Ui.dp(this, 7));
        // The dot+label+tick content alone is well under it — this app's 48dp touch-target
        // floor binds every tappable row, not only its controls (see Ui#measureRow and
        // every setMinimumHeight(48dp) beside it).
        row.setMinimumHeight(Ui.dp(this, 48));
        row.setOnClickListener(tap);
        row.setOnTouchListener(new Ui.Press());

        View dot = new View(this);
        android.graphics.drawable.GradientDrawable g = new android.graphics.drawable.GradientDrawable();
        g.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        // PASS F - PROGRESS IS LIME, NOT GREEN. Look#SAFE names two sanctioned uses and
        // explicitly forbids the third this was: green meaning "fine / good / done" on a
        // figure, chip or row. A completed setup step is progress, which is what ACCENT is
        // for, and every green spent on progress makes the green that means "the pump is
        // confirmed vented" a little less believable.
        if (done) g.setColor(Ui.ACCENT);
        else { g.setColor(Ui.SURFHI); g.setStroke(Ui.dp(this, Look.TICK_RING_DP), Ui.FAINT); }
        dot.setBackground(g);
        LinearLayout.LayoutParams dotLp = new LinearLayout.LayoutParams(
                Ui.dp(this, Look.TICK_DOT_DP), Ui.dp(this, Look.TICK_DOT_DP));
        dotLp.rightMargin = Ui.dp(this, Look.S3);
        row.addView(dot, dotLp);

        TextView t = new TextView(this);
        t.setText(label);
        t.setTextColor(Ui.TEXT);
        t.setTextSize(Look.SP_BODY);
        row.addView(t, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        if (done) {
            TextView tick = new TextView(this);
            tick.setText("✓");
            tick.setTextColor(Ui.ACCENT);      // pass F - progress, not a pump verdict
            tick.setTextSize(Look.SP_BODY);
            row.addView(tick);
        }

        Ui.group(row, label + (done ? ". Done" : ". Not done yet") + ". Opens the right screen.");
        card.addView(row);
    }

    /** The popup's "Dismiss" button (its negative button) — hides it permanently regardless
     *  of what is still outstanding, and never shows it again on its own. Mirrors every
     *  other "flip a persisted flag, save" tap in the app (e.g. TogglePullBuzz); the redraw is
     *  the dialog's own default auto-dismiss (see {@link SetupPopupDismissListener}) rather
     *  than a showHome() rebuild — the popup is not part of Today's view tree. */
    private final class DismissSetupTap implements DialogInterface.OnClickListener {
        @Override public void onClick(DialogInterface d, int which) {
            model.setupDismissed = true;
            Store.save(SessionActivity.this, model);
        }
    }

    /** The checklist's "Connect your pump" row — the same door the header's own Connect
     *  button and Settings use, not a new one. */
    private final class OpenConnectTap implements View.OnClickListener {
        @Override public void onClick(View v) { openConnect(); }
    }

    /** The checklist's "Run the starter routine" row: selects the seeded Starter Routine,
     *  then the same confirm-dialog path START itself uses — see {@link
     *  #selectAndConfirmStart}. */
    private final class StartStarterRoutineTap implements View.OnClickListener {
        @Override public void onClick(View v) { selectAndConfirmStart(Model.SEED_STARTER_ROUTINE_ID); }
    }

    /**
     * Selects `routineId` — persisted immediately, the same as every other deliberate
     * selection in the app ({@link PickRoutineTap}, {@link SelectRoutineTap}) — and
     * redraws Today BEFORE showing {@link #confirmStart}'s dialog. The dialog sits on top
     * of whatever is already drawn; without the redraw here, Cancel would leave Today's
     * hero card naming whichever routine was selected before this call, disagreeing with
     * the selection that is now actually persisted underneath it.
     *
     * Shared by the checklist's {@link StartStarterRoutineTap} and the "Start last
     * routine" app shortcut ({@link #handleShortcutIntent}) — both need exactly this:
     * pick a specific routine, then ask before running it.
     */
    void selectAndConfirmStart(String routineId) {
        model.selected = routineId;
        Store.save(this, model);
        showHome();
        confirmStart();
    }

    /**
     * ONE OF THE THREE ACTION BUTTONS on Today — a glyph, a heavy label, and a plain
     * caption saying what the tap does, on one 60dp target.
     *
     * WHY A CAPTION INSIDE THE BUTTON rather than a note under it: these three used to be
     * distinguished only by the words on them, and "Manual run · no routine" reads as a
     * setting as easily as an action. A glyph gives each one a shape the eye can find
     * without reading, and the caption puts the explanation on the thing it explains.
     * Built as spans on the Button's own text rather than as a stack of TextViews, so the
     * whole row stays ONE focus stop and one 48dp-plus target with nothing to mis-hit.
     *
     * COLOUR. `fill` is a bright primary (Ui.ACCENT for START; Ui.GOOD is equally accepted)
     * and Ui.SURFHI for the other two — the caller's
     * choice, stated at the call site where the hierarchy is visible. The two secondary
     * ones take a hairline edge (Ui.LINE, the app's divider colour) so they read as
     * raised controls rather than as list rows; the edge is deliberately NOT a state
     * colour, because an edge that is teal or amber would be claiming something about the
     * pump that a button on the home screen has no business claiming.
     */
    private Button actionButton(LinearLayout parent, String glyph, String label,
                                 String caption, int fill) {
        Button b = new Button(this);
        String text = glyph + "   " + label + "\n" + caption;
        android.text.SpannableString sp = new android.text.SpannableString(text);
        int capFrom = text.length() - caption.length();
        int on = Ui.labelOn(fill);
        // The caption is smaller and quieter than the label, but it must still clear AA
        // against the fill it sits on. On a BRIGHT primary — green (Ui.GOOD) or lime
        // (Ui.ACCENT), the fill the START button actually uses — that means the same
        // near-black label colour the label itself uses: Ui.DIM is a grey chosen against
        // dark surfaces and would very nearly vanish on either (~2.2:1 on lime, far under
        // AA). On the dark secondary fills DIM is exactly right, and is the pairing Look
        // pins for a caption on a surface.
        boolean bright = (fill == Ui.GOOD || fill == Ui.ACCENT);
        int capColour = bright ? on : Ui.DIM;
        sp.setSpan(new android.text.style.RelativeSizeSpan(0.72f), capFrom, text.length(),
                   android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        sp.setSpan(new android.text.style.ForegroundColorSpan(capColour), capFrom, text.length(),
                   android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        sp.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD), 0, capFrom,
                   android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        b.setText(sp);
        b.setAllCaps(false);
        b.setTextSize(Look.SP_HEADING);
        b.setTextColor(on);
        b.setGravity(Gravity.LEFT | Gravity.CENTER_VERTICAL);
        android.graphics.drawable.GradientDrawable bg = Ui.roundRect(this, fill, Look.R_CTRL);
        if (!bright) bg.setStroke(Ui.dp(this, 1), Ui.LINE);
        b.setBackground(bg);
        b.setPadding(Ui.dp(this, 16), Ui.dp(this, 8), Ui.dp(this, 14), Ui.dp(this, 8));
        b.setOnTouchListener(new Ui.Press());
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(this, 60));
        lp.bottomMargin = Ui.dp(this, 8);
        parent.addView(b, lp);
        return b;
    }

    /**
     * The hero card — the selected routine as the home screen's centrepiece: its name and the
     * three facts that say what START will do (duration, PEAK TARGET, stages). Three states,
     * each saying what to do next: no routines at all, a routine that cannot run yet, and the
     * ready hero. No amber anywhere here — a selected routine is a PLAN, not the pump under
     * command — and "peak target" keeps a plan figure worded as a plan (defect #07); the
     * routineSec()/peak() it quotes are the same figures the routines list, the editor and the
     * START dialog use, so Today can never quote a shorter routine than they do.
     */
    /**
     * The day pill's text: weekday abbreviation and training status, e.g. "TUE·TRAIN" /
     * "WED·REST" — the first of the three pills pillStrip() draws. Same weekday
     * derivation and the same Schedule#isTodayTraining flag "is today a scheduled day" has
     * always come from; the streak this line used to fold in too is its own pill now
     * (pillStrip() reads it straight from Summary.Stats, not from here).
     */
    private String greetingLine(long now) {
        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.setTimeInMillis(now);
        int dow = cal.get(java.util.Calendar.DAY_OF_WEEK);
        // Calendar's SUNDAY is 1; Schedule's week starts on Monday.
        int idx = (dow == java.util.Calendar.SUNDAY) ? 6 : dow - 2;
        String day = (idx >= 0 && idx < Schedule.DAY_ABBR.length)
            ? Schedule.DAY_ABBR[idx] : "";
        boolean training = model.sched != null && model.sched.isTodayTraining(now);
        return (day + "·" + (training ? "TRAIN" : "REST")).toUpperCase(Locale.US);
    }

    /**
     * THE STAGE RAIL as it appears OFF the run screen — on the routine card and the
     * Library cards. One segment per stage, widths in proportion to how long each runs
     * (Insight#railShares) and coloured by what the stage is FOR (Insight#railRole):
     * lime warming up, AMBER working, green coming down.
     *
     * The amber here is earned in the same way it is everywhere else: the work stage is
     * the stretch where the pump is at its deepest, and the rail is a picture of pressure
     * over the routine. The proportions are the whole claim the graphic makes, which is
     * why they are computed in the pure layer and asserted rather than being three
     * equal-weight Views that look like a rail without being one.
     */
    /**
     * WHAT COLOUR A STAGE IS, asked of the STAGE rather than of its name and position.
     *
     * The rail and its caption each computed this themselves from
     * {@code Insight.railRole(name, index, count)} - a heuristic that reads the stage's NAME
     * and whether it is last. On a six-stage prescription it got two of them wrong at once:
     * the final work block was called a cool-down because it happened to be last, and the
     * rests were painted amber, the one colour this app reserves for the pump being under
     * pressure, on the one stage where by definition it is not.
     *
     * A stage already knows what it is - {@link Model.Stage#rest}, {@link
     * Model.Stage#retention}, its own colour - so it is asked. Rail and caption both call
     * this, so they cannot describe the same stage two different ways again.
     *
     * THREE MEANINGS, NOT SIX: work is the action colour, preparation and the retention hold
     * take the block palette's own (chosen precisely because it is none of the state
     * colours), and a rest is faint - it is an absence, and the rail draws it as a gap.
     */
    int railColourOf(Model.Stage st) {
        if (st == null) return Ui.ACCENT;
        if (st.rest) return Ui.FAINT;
        if (st.retention || st.colour == Model.STAGE_WARM || st.colour == Model.STAGE_COOL)
            return Look.BLOCKS[2];
        return Ui.ACCENT;
    }

    void stageRailFor(ViewGroup parent, Model.Routine r) {
        if (r == null || r.stages.isEmpty()) return;
        /* ONE STAGE BAR (0.10 run-screen redesign). Today, the Library card and the run screen
         * draw the routine's stages through the SAME model (StageBar) and the SAME view
         * (StageBarView); this is its static face - every stage in the colour railColourOf
         * gives it, sized by time (Insight#railShares, so an empty stage still shows), a rest
         * the thin line it has always been.
         *
         * PASS F - THE COOL-DOWN SEGMENT IS NOT GREEN. The rail needs three distinguishable
         * colours and reached for the palette's three brightest, which put "confirmed vented"
         * on a stage that has not run yet. railColourOf answers from Look.BLOCKS, chosen
         * BECAUSE none of them is a state colour: a segment is a position, not a claim. */
        java.util.List<StageBar.Segment> segs =
            StageBar.build(r.stages, model.plan(r), -1, 0L, null, null, false);
        int[] cols = new int[segs.size()];
        for (int i = 0; i < cols.length; i++) cols[i] = railColourOf(r.stages.get(segs.get(i).stage));
        StageBarView rail = new StageBarView(this);
        rail.set(segs, cols, false);
        // The mockup's rail is a 7dp bar with fully rounded ends.
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(this, 7));
        lp.topMargin = Ui.dp(this, 4);
        parent.addView(rail, lp);
    }

    /** The sets a stage plays, in order, named — "Gentle Hold · Progressive Ramp". A set
     *  whose id no longer resolves is simply left out rather than printed as a blank or an
     *  id: the stage list is a description, and a description of a set that is gone says
     *  nothing a reader can act on. */
    String stageSetNames(Model.Stage st) {
        if (st == null || st.setIds == null) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < st.setIds.size(); i++) {
            Model.Set s = model.set(st.setIds.get(i));
            if (s == null) continue;
            if (sb.length() > 0) sb.append(" · ");
            sb.append(s.name);
        }
        return sb.toString();
    }

    /** The rail's caption — each stage named with its own length, then the peak. The
     *  pressure goes through Model.Fmt.p, so it follows the display unit and reads
     *  negative in inHg. */
    private CharSequence railCaption(Model.Routine r) {
        if (r == null || r.stages.isEmpty()) return "";
        long[] durs = model.stageDurationsMs(r);
        android.text.SpannableStringBuilder sb = new android.text.SpannableStringBuilder();
        for (int i = 0; i < r.stages.size(); i++) {
            if (i > 0) sb.append("  ·  ");
            int at = sb.length();
            sb.append(r.stages.get(i).name).append(' ')
              .append(Model.Fmt.t((i < durs.length ? durs[i] : 0) / 1000));
            // EACH STAGE'S WORDS IN ITS OWN SEGMENT'S COLOUR, from railColourOf - the
            // same method the rail paints with, so a bar and the word under it can never
            // again say different things about one stage.
            sb.setSpan(new android.text.style.ForegroundColorSpan(
                           railColourOf(r.stages.get(i))), at, sb.length(),
                       android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        }
        // The peak is not a stage and takes no stage colour — it stays the caption's own
        // dim, so the three coloured names remain the only marked thing in the line.
        sb.append("  ·  peak ").append(Model.Fmt.p(model.workPeakKpa(r)));
        return sb;
    }

    /**
     * WHAT HAPPENED LAST TIME. The most useful single line the app can put on Today that
     * is not about what to do next: when, how long, what pressure was actually reached,
     * and what the measurements did. It taps through to that session's summary.
     *
     * Absent entirely when nothing has been filed — an empty "last session" card is a
     * placeholder, and this screen already has an empty state that says something useful.
     * Every pressure through Model.Fmt.p and every delta through Model.Fmt.d, so the units
     * follow the setting and a loss reads as a loss.
     */
    private void lastSessionCard() {
        if (model.sessLog.all.isEmpty()) return;
        Model.Sess s = model.sessLog.all.get(0);

        // A PLAIN CARD. It wore a violet left edge (violet is the measurement channel) so
        // Today's cards were told apart by a mark at their edge; coloured edges are now kept
        // for warnings and faults only (owner's pick, polish item 3). The words "Last
        // session" at the start of the line say what it is.
        LinearLayout h = new LinearLayout(this);
        h.setOrientation(LinearLayout.HORIZONTAL);
        h.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
        Ui.lift(this, h, Ui.ELEV_CARD);
        h.setPadding(Ui.dp(this, 16), Ui.dp(this, 11), Ui.dp(this, 16), Ui.dp(this, 11));

        // ONE COMPACT LINE (Stage B task 8), per the locked visual reference
        // (dist/final-design.html section 1/TODAY): a single Look.SP_CAPTION row —
        // `LAST · AUG 25 · 6:12 · PEAK −6.2 · Δ +0.3CM` — rather than the bold title
        // row ("Last session · <date>") plus a separate DIM fact row this card used
        // to stack underneath it. Every fact below is the exact same computation the
        // two-line version ran (date, duration, peak, before→after delta); only how
        // they are laid out has changed.
        StringBuilder sb = new StringBuilder();
        sb.append("Last session  ·  ").append(dayLabel(s.ts));
        sb.append("  ·  ").append(Model.Fmt.t(s.durSec));
        // A session that produced no real reading says so rather than printing a peak of
        // nothing — 0.0 from this device means NO MEASUREMENT, never ambient.
        sb.append("  ·  peak ").append(s.peakKpa == null ? "no reading"
                                                        : Model.Fmt.p(s.peakKpa.doubleValue()));
        // Model.Fmt.d() is the PRESSURE-delta formatter — it converts kPa/inHg/cmHg and
        // FLIPS SIGN for mercury units (see its own doc). afterLenCm is a length delta in
        // cm (Model.Sess#afterLenCm), the same field Export.java and Summary.cm() print
        // through Model.Fmt.lenDelta() — the correct formatter, which already appends its
        // own unit, so no literal " cm" suffix belongs after it here either.
        if (s.afterLenCm != null)
            sb.append("  ·  before→after ").append(Model.Fmt.lenDelta(s.afterLenCm.doubleValue()))
              .append(s.afterComparable ? "" : " (not like-for-like)");

        TextView t = new TextView(this);
        t.setText(sb.toString());
        t.setTextColor(Ui.DIM);
        t.setTextSize(Look.SP_CAPTION);
        t.setSingleLine(true);
        t.setEllipsize(android.text.TextUtils.TruncateAt.END);
        h.addView(t, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        Ui.group(h, A11y.collapse(sb.toString()) + ". Opens the session history.");
        h.setMinimumHeight(Ui.dp(this, 48));   // one tap target, so the floor binds the row
        h.setOnClickListener(new OpenHistoryTap());
        h.setOnTouchListener(new Ui.Press());
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.bottomMargin = Ui.dp(this, 8);
        body.addView(h, lp);
    }

    private final class OpenHistoryTap implements View.OnClickListener {
        @Override public void onClick(View v) { showSessionHistory(); }
    }

    /**
     * F1 FIX - THE LEAD STILL HAS TO BE SEEN when the hero cannot draw.
     *
     * heroRoutine returns early in two states - nothing selected, and a selection with no
     * usable sets - and folding the remainder and up-next cards INTO it quietly took them
     * with it. Those are precisely the states where somebody most needs to be told what to
     * run: an unfinished session and a broken selection at the same time would have left
     * Today with an explanation of the empty library and no way out of it.
     *
     * So the lead gets its own card in those two cases, with the escapes under it.
     */
    private void nowFallbackCard() {
        long now = System.currentTimeMillis();
        LinearLayout c = Ui.col(this);
        c.setBackground(Ui.popRing(this));
        Ui.lift(this, c, Ui.ELEV_POP);
        c.setPadding(Ui.dp(this, 16), Ui.dp(this, 15), Ui.dp(this, 16), Ui.dp(this, 15));
        boolean led = nowLead(c, now);
        // The remainder's lead ends on its row of links, with no rule of its own (it has a
        // card to itself above a loaded routine); here the escapes follow it, so draw one.
        if (led && hasRemainderToday()) Ui.divider(this, c);
        nowActions(c);
        if (!led && model.routines.isEmpty()) return;   // nothing to say and nowhere to go
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.bottomMargin = Ui.dp(this, 10);
        body.addView(c, lp);
    }

    private void heroRoutine(Model.Routine sel, int selPresets) {
        if (sel == null) {
            nowFallbackCard();
            Ui.card(this, body, "No routines yet",
                 "A routine is what START runs. Open Library below and tap “+ New routine”, "
                 + (model.sets.isEmpty()
                     ? "then add a set to its stage — the set library is empty too, so create "
                       + "one in Sets first."
                     : "then add sets to its stage from the library."));
            return;
        }
        if (selPresets == 0) {
            nowFallbackCard();
            Ui.card(this, body, "Selected  ·  " + sel.name + "  —  nothing to run",
                 "This routine has no usable sets, so there is nothing for the pump to do. "
                 + (model.sets.isEmpty()
                     ? "The set library is empty: create a set in Sets, then add it to this "
                       + "routine's stage."
                     : "Open it in Library, tap its stage, and add sets from the library.")
                 + (sel.stages.isEmpty() ? "  It has no stages yet either." : ""));
            return;
        }

        LinearLayout c = Ui.col(this);
        long heroNow = System.currentTimeMillis();
        heroReason = null;
        /* ONE MAIN ACTION WHEN A SESSION IS HALF DONE (owner's pick, polish item 7).
         *
         * With a remainder to finish, this card used to lead with three stacked buttons and
         * then show the whole loaded routine with its own START under them - four ways to
         * start something, all at once. Now the remainder is a card of its own with ONE lime
         * button, and the loaded routine is a single row under it: "OR RUN WHAT'S LOADED",
         * its short name, a chevron.
         *
         * THE ROW OPENS THE CARD IT STANDS FOR, IN PLACE - it never starts anything. The
         * details and START it hides are the very views drawn here otherwise, so START is
         * the same Tap.START through confirmStart(), with the same consent and the same gate,
         * and nothing about starting has a second path. Opening in place rather than jumping
         * to another screen keeps the finish offer on screen above it, so looking at the
         * loaded run is not a decision about the remainder.
         *
         * Without a remainder nothing changes: the loaded routine IS the main action. */
        boolean resume = hasRemainderToday();
        if (bodyArrived) heroLoadedOpen = false;   // a fresh visit to Today starts folded
        LinearLayout into = c;                     // where the loaded routine's details go
        boolean led;
        if (resume) {
            LinearLayout rc = Ui.col(this);
            rc.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
            Ui.lift(this, rc, Ui.ELEV_POP);
            // No bottom padding: the links' own 48 dp row is the card's last line.
            rc.setPadding(Ui.dp(this, 16), Ui.dp(this, 16), Ui.dp(this, 16), 0);
            remainderLead(rc);
            LinearLayout.LayoutParams rlp = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            rlp.bottomMargin = Ui.dp(this, TODAY_CARD_GAP);
            body.addView(rc, rlp);
            led = true;

            c.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CARD));
            Ui.lift(this, c, Ui.ELEV_CARD);
            c.setPadding(Ui.dp(this, 16), Ui.dp(this, 6), Ui.dp(this, 16), Ui.dp(this, 6));
            into = Ui.col(this);
            loadedRow(c, into, sel);
            // The plan's notices are news, not details: they stay out of the fold.
            planNoticeChip(c);
            levelUpChip(c);
            c.addView(into);
        } else {
            c.setBackground(Ui.popRing(this));
            Ui.lift(this, c, Ui.ELEV_POP);
            c.setPadding(Ui.dp(this, 16), Ui.dp(this, 15), Ui.dp(this, 16), Ui.dp(this, 15));
            // F1 - what is actually about NOW, at the top of the one card that is about now.
            led = nowLead(c, heroNow);
        }

        // 7B (owner pick): the hero IS Today's one block — its kicker carries the
        // plan-choice door that used to be a separate card above it. Folded under the
        // loaded row, the row says "or run what's loaded", so the kicker says the plan.
        TextView label = new TextView(this);
        label.setText((resume ? "TODAY'S SESSION  ·  " + todayPlanLabelNow(heroNow)
                    : led ? "OR RUN WHAT IS LOADED"
                    : heroReason != null
                      ? "UP NEXT  ·  " + heroReason.toUpperCase(Locale.US)
                      : "TODAY'S SESSION  ·  " + todayPlanLabelNow(heroNow)));
        label.setTextColor(Ui.FAINT);
        label.setTextSize(Look.SP_MICRO);
        label.setMinHeight(Ui.dp(this, 32));
        label.setOnClickListener(new PickTodayPlan());
        label.setContentDescription("Today is set to " + todayPlanLabelNow(heroNow)
            + ". Opens the choices.");
        into.addView(label);
        if (!resume) {
            planNoticeChip(c);
            levelUpChip(c);
        }

        // The name and a "READY" pill on ONE row. "ready to run" was the tail of the grey
        // sub-line, which is where a fact goes to be skipped; as a lime pill beside the
        // name it is the first thing read after the name itself. Lime because readiness is
        // about the ACTION this card offers — it is not a claim about the pump, so it is
        // not amber, and it is not a safety confirmation, so it is not green.
        LinearLayout nameRow = new LinearLayout(this);
        nameRow.setOrientation(LinearLayout.HORIZONTAL);
        nameRow.setGravity(Gravity.CENTER_VERTICAL);
        nameRow.setPadding(0, Ui.dp(this, 3), 0, Ui.dp(this, 1));

        TextView name = new TextView(this);
        name.setText(sel.name);
        name.setTextColor(Ui.TEXT);
        name.setTextSize(Look.SP_TITLE);
        name.setTypeface(name.getTypeface(), android.graphics.Typeface.BOLD);
        /* TWO LINES BEFORE AN ELLIPSIS. A minted name ends in its prescription, so
         * truncating from the end cut the numbers and kept the word "Trainer" - the least
         * informative part of the string was the part that always survived. */
        name.setSingleLine(false);
        name.setMaxLines(2);
        name.setEllipsize(android.text.TextUtils.TruncateAt.END);
        nameRow.addView(name, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        TextView ready = Ui.microLabel(this, null, "ready", Ui.ACCENT);
        ready.setBackground(Ui.roundRect(this, Ui.ACCENT_DIM, Look.R_PILL));
        ready.setPadding(Ui.dp(this, Look.S3), Ui.dp(this, 3), Ui.dp(this, Look.S3),
                         Ui.dp(this, 3));
        ready.setTypeface(ready.getTypeface(), android.graphics.Typeface.BOLD);
        nameRow.addView(ready);
        into.addView(nameRow);

        TextView sub = new TextView(this);
        /* CYCLES, NOT PRESETS. A preset is a wire slot, and since the mint began writing
         * one set of N cycles rather than N sets of one, the preset count stopped tracking
         * anything a person recognises: a routine the Trainer describes as "10x2.0min" read
         * "5 presets" here. Cycles is the unit every other surface already speaks in - the
         * prescription, the run screen's planned/delivered pair, the summary - and it is
         * counted by the same Manual#cycles rule they all use.
         *
         * THE WORK CYCLES, not every cycle: the Trainer calls this same routine
         * "10x2.0min" one tab away, and counting the warm-up's ramp steps too would have
         * the two screens name one routine with two numbers and neither explain the gap.
         * The warm-up is not hidden - the rail and its caption are directly below.
         *
         * selPresets still GATES the card above (a routine with no presets genuinely has
         * nothing to send); only what is printed changes. */
        int selCycles = model.workCycles(sel);
        sub.setText(selCycles + " cycle" + (selCycles == 1 ? "" : "s"));
        sub.setTextColor(Ui.DIM);
        sub.setTextSize(Look.SP_CAPTION);
        sub.setPadding(0, 0, 0, Ui.dp(this, 13));
        into.addView(sub);

        // THE STAGE RAIL — one segment per stage, WIDTHS IN PROPORTION to how long each
        // runs (Insight#railShares), coloured by what the stage is for. It is the same
        // rail the run screen paints, so a routine looks on Today like it will look while
        // it plays, and "8 of the 11 minutes are work" is a thing the eye reads rather
        // than a sentence it has to parse.
        stageRailFor(into, sel);

        TextView railText = new TextView(this);
        railText.setText(railCaption(sel));
        railText.setTextColor(Ui.DIM);
        railText.setTextSize(Look.SP_CAPTION * 0.95f);
        railText.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 10));
        into.addView(railText);

        LinearLayout tiles = new LinearLayout(this);
        tiles.setOrientation(LinearLayout.HORIZONTAL);
        heroStat(tiles, Model.Fmt.t(model.routineSec(sel)), "DURATION");
        heroStat(tiles, Model.Fmt.p(model.workPeakKpa(sel)), "PEAK TARGET");
        heroStat(tiles, String.valueOf(sel.stages.size()),
                 sel.stages.size() == 1 ? "STAGE" : "STAGES");
        into.addView(tiles);
        // 7B: START lives ON the session it starts. The one lime primary of the screen —
        // the four-button block below keeps only the non-primary doors. Under a remainder
        // it is folded into the loaded row, so the finish button is the one lime primary.
        Button heroGo = Ui.big(this, into, "▶ START", Ui.ACCENT);
        heroGo.setContentDescription("Start session, run " + A11y.collapse(sel.name));
        heroGo.setOnClickListener(new Tap(Tap.START));
        dayProgressLine(into, heroNow);       // F4
        weekNudge(into);
        nowActions(into);                     // F3 + F5

        // One focus stop reading the whole card as a sentence, and hiding the tile labels
        // from being read as loose fragments — the same treatment Ui.card gives its title/sub.
        Ui.group(into, "Selected routine " + A11y.collapse(sel.name) + ". Duration "
            + Model.Fmt.t(model.routineSec(sel)) + ", peak target " + Model.Fmt.p(model.workPeakKpa(sel))
            + ", " + sel.stages.size() + (sel.stages.size() == 1 ? " stage" : " stages")
            + ", " + selCycles + (selCycles == 1 ? " cycle" : " cycles") + ", ready to run.");

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.bottomMargin = Ui.dp(this, resume ? TODAY_CARD_GAP : 10);
        body.addView(c, lp);

        // WAVE 4 ITEM 10 (owner pick 10B): ONE door under the hero for running a single
        // set — the sheet holds recents, favourites and the way to everything else. The
        // Sets tab is gone; this is where "just run that one set" now lives.
        quickRunCard();
    }

    /** Whether the loaded routine's details are open under the resume card (item 7). Kept
     *  across a redraw of Today, and folded again whenever Today is arrived at afresh. */
    private boolean heroLoadedOpen;

    /**
     * THE LOADED ROUTINE AS ONE ROW, under a remainder: "OR RUN WHAT'S LOADED", its short
     * name and work cycles, a chevron. A tap unfolds `details` - the loaded card's own
     * views, START included - in place, and the chevron turns down; the name line steps
     * aside while they are open, since the full name is the first thing in them.
     */
    private void loadedRow(LinearLayout card, LinearLayout details, Model.Routine sel) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setMinimumHeight(Ui.dp(this, 48));
        row.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));

        LinearLayout words = new LinearLayout(this);
        words.setOrientation(LinearLayout.VERTICAL);
        todayCardLabel(words, "OR RUN WHAT'S LOADED", Ui.DIM);
        int cycles = model.workCycles(sel);
        String shortName = Say.mintTitle(sel.name) + " · " + cycles
            + (cycles == 1 ? " cycle" : " cycles");
        TextView name = new TextView(this);
        name.setText(shortName);
        name.setTextColor(Ui.TEXT);
        name.setTextSize(Look.SP_BODY);
        name.setTypeface(MEDIUM);
        name.setSingleLine(true);
        name.setEllipsize(android.text.TextUtils.TruncateAt.END);
        name.setPadding(0, Ui.dp(this, 2), 0, 0);
        words.addView(name);
        row.addView(words, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        ImageView chev = Ui.iconView(this, R.drawable.ic_chevron_right, Ui.DIM, 20);
        LinearLayout.LayoutParams chLp = (LinearLayout.LayoutParams) chev.getLayoutParams();
        chLp.leftMargin = Ui.dp(this, 8);
        row.addView(chev, chLp);

        row.setOnClickListener(new LoadedRowTap(details, name, chev, shortName));
        row.setOnTouchListener(new Ui.Press());
        paintLoadedRow(row, details, name, chev, shortName, heroLoadedOpen);
        card.addView(row, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    }

    private void paintLoadedRow(View row, View details, View name, View chev,
                                String shortName, boolean open) {
        details.setVisibility(open ? View.VISIBLE : View.GONE);
        name.setVisibility(open ? View.GONE : View.VISIBLE);
        chev.setRotation(open ? 90f : 0f);
        Ui.group((ViewGroup) row, "Or run what's loaded: " + A11y.collapse(shortName)
            + (open ? ". Shown below, with START. Hides it." : ". Shows it, with START."));
    }

    private final class LoadedRowTap implements View.OnClickListener {
        private final View details, name, chev;
        private final String shortName;
        LoadedRowTap(View details, View name, View chev, String shortName) {
            this.details = details; this.name = name; this.chev = chev;
            this.shortName = shortName;
        }
        @Override public void onClick(View v) {
            heroLoadedOpen = !heroLoadedOpen;
            paintLoadedRow(v, details, name, chev, shortName, heroLoadedOpen);
        }
    }

