            Ui.dress(SessionActivity.this, Ui.dialog(SessionActivity.this)
                .setTitle("Routine name")
                .setView(input)
                .setPositiveButton("Rename", new RenameRoutineConfirm(input))
                .setNegativeButton("Cancel", null)
                .show());
