    /**
     * Stage editor, per #v-stage-edit / renderStageEdit(): rename, recolour, and the
     * ordered set rows with ▲▼ reorder and ✕ remove. Removing a set here only drops
     * its id from the stage's list — the set itself lives on in model.sets and stays
     * fully intact for the library and every other stage (bug class: a set must be
     * returned to the library, never deleted, by leaving a stage).
     */
    void showStageEdit() {
        Model.Routine r = model.routine(editRoutId);
        if (r == null || editStageIdx < 0 || editStageIdx >= r.stages.size()) {
            showRoutines(); return;                 // stale state from the caller, not a
        }                                             // background render ejecting the user
        Model.Stage st = r.stages.get(editStageIdx);

        body.removeAllViews();
        // Back to the routine editor. Colour, name, order and membership all save live, so
        // this is a return (DoneStageTap, unchanged) — moved onto the header arrow.
        header(body, "Stage  ·  " + r.name, new DoneStageTap());

        Button rename = Ui.flat(this, body, "Stage name: " + st.name);
        rename.setSingleLine(true);
        rename.setEllipsize(android.text.TextUtils.TruncateAt.END);
        rename.setOnClickListener(new RenameStageTap());

        // A REST STAGE'S WHOLE EDITOR: a name and a duration. No colour (a rest wears the
        // one colour that means "nothing is being commanded", and letting it be repainted
        // Warm would put a rest in the palette of the things that pull), no set list, no
        // picker. Everything below this branch is about sets, and a rest has none.
        if (st.rest) {
            Ui.stepperRow(this, body, "Rest for  (0:30–60:00, 30 s steps)",
                Model.Fmt.t(st.restSec),
                new BumpRestStage(-1), new BumpRestStage(+1), "rest duration");
            Ui.note(this, body,
                "The cuff is vented and nothing is commanded for the whole length of a rest. It counts toward the routine's duration.");
            // polish LB-6: delete moved into the stage as the routine editor opens it.
            Ui.note(this, body, "Reorder it in the routine editor, like any other stage; "
                + "Delete stage is inside the stage there.");
            return;
        }

        Ui.note(this, body, "Colour");
        Ui.row(this, body,
            new String[]{ (st.colour == Model.STAGE_WARM ? "● " : "○ ") + "Warm",
                          (st.colour == Model.STAGE_WORK ? "● " : "○ ") + "Work" },
            new View.OnClickListener[]{ new StageColourTap(Model.STAGE_WARM),
                                         new StageColourTap(Model.STAGE_WORK) });
        Ui.row(this, body,
            new String[]{ (st.colour == Model.STAGE_COOL ? "● " : "○ ") + "Cool" },
            new View.OnClickListener[]{ new StageColourTap(Model.STAGE_COOL) });

        Ui.note(this, body, "Sets in this stage — ▲▼ to reorder");
        for (int j = 0; j < st.setIds.size(); j++) {
            Model.Set s = model.set(st.setIds.get(j));
            if (s == null) continue;                // a dangling id is never a phantom row

            LinearLayout row = new LinearLayout(this);
            row.setOrientation(LinearLayout.HORIZONTAL);
            row.setGravity(Gravity.CENTER_VERTICAL);
            row.setBackground(Ui.roundRect(this, Ui.SURF, Look.R_CTRL));
            row.setPadding(Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6));

            // ▲ ▼ ✕ are the app's only icon-ONLY controls outside the camera. Named from
            // the set they act on and its position, because "up" repeated down a stage of
            // six sets says nothing about which one moves.
            String where = " (" + (j + 1) + " of " + st.setIds.size() + ")";
            Button up = Ui.mini(this, "▲");
            up.setEnabled(j > 0);
            up.setContentDescription("move " + s.name + " up" + where);
            up.setOnClickListener(new MoveSetTap(j, -1));
            Button down = Ui.mini(this, "▼");
            down.setEnabled(j < st.setIds.size() - 1);
            down.setContentDescription("move " + s.name + " down" + where);
            down.setOnClickListener(new MoveSetTap(j, 1));

            TextView label = new TextView(this);
            // A rest has no pressures to print — the field dump would read "0.0 / 0.0 ·
            // 0% ·  2:00" and describe a preset that is never sent. Set#line already says
            // what a rest is in words, so the row asks it rather than formatting zeros.
            // The trailing " ›" marks the name itself as tappable — same signal a chevron
            // gives anywhere else in the app — since it now opens this set's editor
            // (OpenSetEdit, the identical listener Library's set cards use), matching the
            // raised-card look this row already borrows from Library.
            label.setText(s.name + " ›" + "\n" + (s.rest ? s.line()
                : Model.Fmt.p(s.up) + " / " + Model.Fmt.p(s.lo)
                  + "  ·  " + s.sp + "%  ·  " + Model.Fmt.t(s.dur)));
            label.setTextColor(Ui.TEXT);
            label.setTextSize(Look.SP_LABEL);
            label.setOnClickListener(new OpenSetEdit(s.id));
            label.setOnTouchListener(new Ui.Press());
            label.setMinimumHeight(Ui.dp(this, 48));
            label.setContentDescription("Edit " + s.name + ", opens the set editor");
            LinearLayout.LayoutParams labelLp =
                new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
            labelLp.leftMargin = Ui.dp(this, 8); labelLp.rightMargin = Ui.dp(this, 8);

            Button remove = Ui.mini(this, "✕");
            remove.setContentDescription("remove " + s.name + " from this stage" + where);
            remove.setOnClickListener(new RemoveSetTap(j));

            row.addView(up); row.addView(down); row.addView(label, labelLp); row.addView(remove);
            LinearLayout.LayoutParams rowLp = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            rowLp.bottomMargin = Ui.dp(this, 8);
            body.addView(row, rowLp);
        }
        if (st.setIds.isEmpty())
            Ui.note(this, body, "No sets yet — add some from the library.");

        Button addSets = Ui.big(this, body, "+ Add sets from library", Ui.GOOD);
        addSets.setOnClickListener(new OpenPickerTap());
        Ui.noteInfo(this, body, "Removing a set from a stage returns it to the library.",
            "Sets in this stage", "Removing a set from a stage returns it to the library — "
            + "nothing is deleted by moving it out.");
        Ui.noteInfo(this, body, "Need pressure to climb through this stage? Use one ramp set.",
            "Sets in this stage", "Need pressure to climb through this stage? Use one ramp set — "
            + "ramp is a mode on the set itself, not something a stage does.");
        // "Done" (return to the routine editor) is now the header arrow; "+ Add sets from
        // library" is left as this screen's single primary action.
    }

