    /* ------------------------------------------------------------ Settings · Data */

    final class ExportLogTap implements View.OnClickListener {
        @Override public void onClick(View v) { shareLog(); }
    }

    /** Capture files on disk that no reading points at. Scoped to the exact name shape
     *  CameraScreen writes (Shot#filename) inside app-private external Pictures — never
     *  a blanket wipe of a directory this app does not fully own. The name test itself is
     *  {@link Backup#isBackupPhotoName} (Task 9) rather than a second copy of the same
     *  "reading-*.jpg" rule: a backup's photos/ folder and this app's own idea of "photo
     *  files that are ours to manage" must never be able to drift apart. */
    File[] orphanPhotoFiles() {
        File dir = getExternalFilesDir(Environment.DIRECTORY_PICTURES);
        if (dir == null) return null;
        File[] all = dir.listFiles();
        if (all == null) return null;
        List<File> out = new ArrayList<File>();
        for (int i = 0; i < all.length; i++) {
            File f = all[i];
            if (!f.isFile()) continue;
            if (!Backup.isBackupPhotoName(f.getName())) continue;
            if (isReferenced(f.getAbsolutePath())) continue;
            out.add(f);
        }
        return out.toArray(new File[out.size()]);
    }

    private boolean isReferenced(String path) {
        for (int i = 0; i < model.measLog.all.size(); i++) {
            Model.Reading r = model.measLog.all.get(i);
            if (r.photoFront != null && path.equals(r.photoFront.path)) return true;
            if (r.photoSide != null && path.equals(r.photoSide.path)) return true;
            if (r.photoTop != null && path.equals(r.photoTop.path)) return true;
        }
        return false;
    }

    /** True when the file is gone afterwards — including when it was already missing,
     *  which is the same outcome from the user's point of view. */
    /**
     * STRAY PHOTOS ARE SWEPT AT START (0.10, the owner's call; WiringCheck invariant 222).
     * Deletes reading-<id>-<view>.jpg files in the photo folder that no reading has the id
     * of or refers to, that no open capture is making, and that are over 24 hours old
     * (StrayPhotos#toDelete says which). Never while the store is unreadable - the model is
     * then the seeded stand-in and every photo would look like a stray. Logs a count, never
     * a name or a path. Best effort: a failure here must not stop the app opening.
     */
    void sweepStrayPhotos() {
        if (Store.storeWasUnreadable()) return;
        try {
            File dir = getExternalFilesDir(Environment.DIRECTORY_PICTURES);
            File[] all = dir == null ? null : dir.listFiles();
            if (all == null) return;
            List<StrayPhotos.Entry> files = new ArrayList<StrayPhotos.Entry>();
            for (int i = 0; i < all.length; i++)
                if (all[i].isFile())
                    files.add(new StrayPhotos.Entry(all[i].getName(), all[i].lastModified()));
            List<String> open = new ArrayList<String>();
            if (measReadingId != null) open.add(measReadingId);
            if (photoReadingId != null) open.add(photoReadingId);
            List<String> gone = StrayPhotos.toDelete(files, model.measLog, open,
                                                     System.currentTimeMillis());
            int swept = 0;
            for (int i = 0; i < gone.size(); i++)
                if (deletePhotoFile(new File(dir, gone.get(i)).getAbsolutePath())) swept++;
            if (!gone.isEmpty())
                log("--- stray photos: " + swept + " of " + gone.size() + " swept (no reading, "
                    + "over 24 h old)");
        } catch (Exception e) {
            log("!! stray photo sweep failed: " + e.getClass().getSimpleName());
        }
    }

    boolean deletePhotoFile(String path) {
        if (path == null || path.length() == 0) return true;
        try {
            File f = new File(path);
            return !f.exists() || f.delete();
        } catch (Exception e) {
            log("!! could not delete " + path + ": " + e);
            return false;
        }
    }


    /* ------------------------------------------------------- measurement history */

    /**
     * Measurement history, per proto/pump-console.html's #v-meashist / renderMeasHist(),
     * Task 8. Entry point is Settings' "Measurement history ›" button above; the header
     * back arrow returns there, matching how this app reaches the screen (the prototype's
     * own "‹ History" back target is a session-run history screen no task in this plan
     * owns yet).
     *
     * Everything period-dependent — the window, its length/girth delta, the row list, the
     * trend chart, the comparability verdict — is derived fresh from mhPeriod/mhPagesLoaded
     * on every render, through Meas.java's pure helpers, never cached across a period
     * switch (bug class: a render must reflect current state, not stale state left over
     * from whichever period was open before).
     */
    int mhPeriod = Meas.PERIOD_3M;

    /**
     * WHICH SERIES THE TREND CHART DRAWS — 0 length, 1 girth. One at a time, chosen by two
     * chips above the plot.
     *
     * WHY ONE. Length and girth are on INDEPENDENT scales (each fitted to its own min/max,
     * because sharing one axis flattens whichever has the smaller natural range), so the
     * plot carried two lines whose vertical positions could not be compared with each other
     * — plus, once goals existed, two dashed goal lines on those two scales. Four lines,
     * two of them meaning something only relative to a scale that is not drawn. Splitting
     * it makes every line on the plot true against the same axis, and the goal line finally
     * has one series it is the goal FOR.
     *
     * Session state, not a setting: it is a way of looking at the page, not a preference
     * about the app, and it resets to length with everything else on entry.
     */
    static final int METRIC_LEN = 0, METRIC_GIR = 1;
    /** S9's volume mini chart — a THIRD thing {@link TrendChart} can draw, but never a
     *  choice on {@link #metricRow}: volume is not a series the picker offers, it is a
     *  second, always-shown picture built once per render (see {@link #volumeSeries},
     *  {@link #trendCard}) and never assigned to {@link #mhMetric}. */
    static final int METRIC_VOL = 2;
    int mhMetric = METRIC_LEN;

    /**
     * WHICH SERIES THE PLOT DRAWS — a MULTI-SELECT of (method, phase) combinations, each
     * encoded as method*10 + phase (see {@link #seriesCode}). Transient on purpose: it is a
     * way of looking at this page, like the period pills and the metric chip beside it, not
     * a preference about the data, so it is not persisted and needs no migration.
     *
     * Empty means "not yet chosen" — {@link #ensureSeriesSelection} then defaults it through
     * the pinned {@link Meas#defaultSeries}: the standardized series plus this metric's
     * goal method's series (so the goal line shows on open), or every series with data when neither is
     * present. Series that no longer have data in the current window/metric are pruned on
     * each render, so a chip can never stand for an empty line.
     */
    final java.util.Set<Integer> mhSeries = new java.util.HashSet<Integer>();

    /**
     * TRUE WHILE THE PERSON HAS CHOSEN NO SERIES: "None", or unticking the last chip (item
     * 14). An empty {@link #mhSeries} otherwise means "not yet chosen" and is filled from
     * Meas#defaultSeries. Without this, "None" could never leave the chart empty - the next
     * render re-ticked the defaults, so the control did something other than its name and
     * the last chip could not be unticked. Cleared by ticking anything, by All, by switching
     * metric (the other metric's chips open on their own defaults) and by a fresh entry to
     * the readings screen. Transient, like the set itself.
     */
    boolean mhSeriesNone = false;
    int mhPagesLoaded = 1;

    /** A plotted series' key: method in the tens place, phase in the ones. */
    static int seriesCode(int method, int phase) { return method * 10 + phase; }
    private static int codeMethod(int code) { return code / 10; }

    /** Compare two dates, Task 9, per proto/pump-console.html's #v-compare / renderCompare.
     *  All the real logic lives in CompareScreen/Compare.java — this is just the door to
     *  it from Measurements' "Compare two dates" button. Its own back button returns here
     *  via renderMeasHist() directly (OpenMeasHistBack below), never openMeasHist(), so
     *  leaving Compare does not reset whatever period/page the user had scrolled to. */
    private void openCompare() {
        enterDest(Nav.SCR_COMPARE);
        // TASK 6 — "Photos & compare" gate — see OpenThenNowTap's own doc for why
        // body.removeAllViews() is called explicitly here rather than left to
        // compare.open()'s own copy of it.
        body.removeAllViews();
        if (appLockGate(AppLock.PHOTOS, new Runnable() {
                @Override public void run() { openCompare(); }
            })) return;
        compare.open();
    }

    final class OpenMeasHistBack implements Runnable {
        @Override public void run() { renderMeasHist(); }
    }

    /** statRow into `body`, the placement every caller but the streak card wants. */
    void statRow(String[] labels, String[] values) {
        statRow(body, labels, values);
    }

    /**
     * The stat tiles, added to `parent` — an explicit parent so the streak card can hold
     * its own tiles INSIDE the card rather than dropping them loose on the page under it.
     *
     * The values have TABULAR digits: they are measured figures (completions, summed
     * duration, a percentage of filed sessions) and every measured figure in this app is
     * tabular, so a changing digit does not shift the ones beside it. They only report, so
     * they are the sans face rather than monospace (Look's type scale).
     */
    void statRow(ViewGroup parent, String[] labels, String[] values) {
        LinearLayout r = new LinearLayout(this);
        r.setOrientation(LinearLayout.HORIZONTAL);
        for (int i = 0; i < labels.length; i++) {
            LinearLayout cell = Ui.col(this);
            TextView v = new TextView(this);
            v.setText(values[i]);
            v.setTextColor(Ui.TEXT);
            v.setTextSize(Look.SP_HEADING);
            Ui.tabular(v);
            v.setGravity(Gravity.CENTER);
            TextView l = new TextView(this);
            l.setText(labels[i]);
            l.setTextColor(Ui.DIM);
            l.setTextSize(Look.SP_MICRO);
            l.setGravity(Gravity.CENTER);
            cell.addView(v); cell.addView(l);
            // Drawn value-above-label, which a service reads in that order — "12,
            // SESSIONS". Grouped so it is one stop, and said label-first so the number
            // arrives already knowing what it counts.
            Ui.group(cell, A11y.collapse(labels[i]).toLowerCase(Locale.US) + " " + values[i]);
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0,
                    ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
            r.addView(cell, lp);
        }
        LinearLayout.LayoutParams rLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rLp.topMargin = Ui.dp(this, 4); rLp.bottomMargin = Ui.dp(this, 8);
        parent.addView(r, rLp);
    }

    /** The LENGTH | GIRTH switch above the plot: a segmented control (item 14), the same
     *  kind of control as the period one above it, since both are ways of looking at this
     *  page. The chosen segment's WORD wears the colour of the series it selects - lime for
     *  length, violet for girth - so the switch and the plot below are visibly one thing.
     *  Neither is green: choosing a metric confirms nothing about the pump. Each segment is
     *  a 48dp target that says whether it is selected (see Ui#segmented). */
    void metricRow(ViewGroup parent) {
        View.OnClickListener[] taps = { new MetricTap(METRIC_LEN), new MetricTap(METRIC_GIR) };
        Ui.Segmented r = Ui.segmented(this, null, new String[]{ "Length", "Girth" }, null,
                mhMetric, taps, new int[]{ Ui.ACCENT, Ui.BODY }, false);
        LinearLayout.LayoutParams rLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rLp.topMargin = Ui.dp(this, Look.S4);
        parent.addView(r.view, rLp);
    }

    /** The (method, phase) series that have data in `oldestFirst` for the current metric. */
    List<int[]> availSeries(List<Model.Reading> oldestFirst) {
        return Meas.seriesWithData(oldestFirst, mhMetric == METRIC_LEN);
    }

    private final class MetricTap implements View.OnClickListener {
        private final int metric;
        MetricTap(int m) { metric = m; }
        @Override public void onClick(View v) {
            mhMetric = metric;
            mhSeriesNone = false;   // a "None" was about the other metric's chips
            rerenderCurrent();
        }
    }

    /**
     * The baseline trend, drawn on a Canvas per Task 8 Step 2 (mirrors the prototype's SVG
     * chart in renderMeasHist): length and girth each scaled to their OWN min/max (Meas.
     * yFractionsFor per series — sharing one scale would flatten whichever series has the
     * smaller natural range). Every dot is filled except a Std-line reading with no hold
     * recorded (Meas#markedApart, STUDY-19 V2). (Meas.unstdRuns' shaded runs are no longer
     * drawn.)
     */
    /** One headline row for the trend: the metric name, its current value (large, in the
     *  measured-teal), and the change over the window with an explicit sign. The number is
     *  read before the shape — this is what tells a user what happened without decoding a
     *  line. The change is not colour-judged good/bad (this is a body measurement, not a
     *  safety state): the sign carries the direction, teal marks it as measured.
     *
     *  `current`/`delta` are each Double.NaN when this metric was never measured in the
     *  relevant reading(s) — {@link Meas#deltaFor} and the per-metric newest-cold lookup
     *  in {@link #trendCard} both use that sentinel now, so a length-only window's girth
     *  headline reads "—", never a fabricated 0.0. The two are independent: a window can
     *  have a real current girth with no comparable girth delta, or vice versa. */
    void trendLead(ViewGroup parent, String metric, double current, double delta,
                           String method, String since) {
        // The headline figures are body measurements, so they mask like every other one.
        // One key per METRIC, so length and girth reveal independently — unlike the
        // since-strip, these are two separate statements about two separate things.
        final String key = measKey("trend:" + metric);
        final boolean hide = blurred(key);
        final boolean hasCurrent = !Double.isNaN(current);
        final boolean hasDelta = !Double.isNaN(delta);
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(0, Ui.dp(this, 2), 0, Ui.dp(this, 2));

        TextView label = new TextView(this);
        label.setText(metric);
        label.setTextColor(Ui.DIM);
        label.setTextSize(Look.SP_MICRO);
        label.setMinWidth(Ui.dp(this, 62));
        row.addView(label);

        /* THROUGH THE CONVERTER, LIKE EVERY OTHER LENGTH ON THIS CARD.
         *
         * `current` and `delta` are CENTIMETRES - storage is always centimetres and the unit
         * setting only picks how a number is DRAWN. These three were formatted with a bare
         * String.format while the unit word beside them still came from Model.Fmt.lenUnit(),
         * so with the size unit set to inches a 15.5 cm reading rendered as "15.5 in" - the
         * headline figure of the card, wrong by a factor of 2.54, beside a stat tile and a
         * chart axis that both convert properly. Three figures for one measurement. */
        TextView value = new TextView(this);
        value.setText(hide ? MASK
            : hasCurrent ? Model.Fmt.lenNum(current) : "—");
        value.setTextColor(Ui.ACCENT);
        Ui.tabular(value);
        value.setTextSize(26);
        row.addView(value);

        /* ...AND WHICH PROTOCOL MEASURED IT. The card plots one line per (method, phase)
         * precisely because readings taken different ways are different measurements of the
         * same body - and then printed its headline figure as a bare number, so the one
         * value the eye lands on first was the only thing on the card that did not say what
         * it was. The locked reference prints "13.1  CM · MSSG"; methodLabel is the same
         * word the legend, the goal lines and the pre/post caption already use. */
        TextView unit = new TextView(this);
        unit.setText(" " + Model.Fmt.lenUnit()
            + (!hide && hasCurrent && method != null ? "  ·  " + method : ""));
        unit.setTextColor(Ui.DIM);
        unit.setTextSize(Look.SP_FIELD_LABEL);
        row.addView(unit);

        /* C8 - AND WHAT THE CHANGE IS AGAINST. "+0.3 this period" beside "Std" read as the Std
         * length's change, and was the newest Std minus the oldest reading of ANY method -
         * a BPEL, a BPSSL (study problem 7). The change is now only ever within the one
         * comparability rule (Meas#periodPair), so the method beside the figure is the
         * method on both ends, and `since` names the reading it is measured from. */
        TextView change = new TextView(this);
        String sign = delta >= 0 ? "+" : "−";
        String against = since != null ? since : "this period";
        change.setText(hide ? "   " + MASK
            : !hasDelta ? "   —"
            : "   " + sign + Model.Fmt.lenNum(Math.abs(delta))
              + " " + against);
        change.setTextColor(Ui.DIM);
        change.setTextSize(Look.SP_CAPTION);
        row.addView(change);

        // A HIDDEN VALUE IS HIDDEN FROM THE READER TOO. Speaking the number a blur is
        // covering would defeat the control for anyone using a screen reader in the exact
        // situation the control exists for.
        row.setContentDescription(hide
            ? metric.toLowerCase(Locale.US) + " hidden — reveal to read it"
            : metric.toLowerCase(Locale.US) + " "
              + (hasCurrent ? "now " + Model.Fmt.lenNum(current) + " "
                              + Model.Fmt.lenUnit()
                              + (method != null ? " by " + method : "") + ", "
                            : "not measured this way, ")
              + (hasDelta ? (delta >= 0 ? "up " : "down ")
                            + Model.Fmt.lenNum(Math.abs(delta)) + " " + against
                          : "no comparable change this period"));
        Ui.group(row, row.getContentDescription().toString());
        parent.addView(row, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    }

    /** One plotted line: the readings of a (method, phase) series, oldest-first, plus the
     *  two tags the chart colours and dashes by. */
    static final class SeriesSpec {
        List<Model.Reading> pts;
        int method, phase;
    }

    /** The selected (method, phase) series as SeriesSpecs, in the enumeration order — the
     *  same order the picker lists them. When `selection` is empty (the report path passes
     *  the whole enumeration through), every available series is built. */
    List<SeriesSpec> buildSelectedSeries(List<Model.Reading> oldestFirst) {
        List<SeriesSpec> out = new ArrayList<SeriesSpec>();
        List<int[]> avail = availSeries(oldestFirst);
        for (int i = 0; i < avail.size(); i++) {
            int method = avail.get(i)[0], phase = avail.get(i)[1];
            if (!mhSeries.contains(Integer.valueOf(seriesCode(method, phase)))) continue;
            SeriesSpec s = new SeriesSpec();
            s.method = method; s.phase = phase;
            s.pts = Meas.ofMethodPhase(oldestFirst, method, phase);
            out.add(s);
        }
        return out;
    }

    /** {tMin, tMax} across every point in `series` — the same span {@link
     *  TrendChart#onDraw} derives internally when it has no {@link
     *  TrendChart#setTimeWindow} override. Exposed here so the S9 volume mini chart can be
     *  pinned to the EXACT X span the measurement chart above it drew (round6-options.html
     *  S9's "aligned X") rather than deriving its own from a different, narrower set of
     *  readings ({@link Meas#volumeCapable} — most readings do not qualify). null when
     *  `series` holds no points at all — nothing to align a second chart's X axis to. */
    static long[] seriesTimeRange(List<SeriesSpec> series) {
        long tMin = Long.MAX_VALUE, tMax = Long.MIN_VALUE;
        for (int si = 0; si < series.size(); si++) {
            List<Model.Reading> pts = series.get(si).pts;
            for (int i = 0; i < pts.size(); i++) {
                long t = pts.get(i).ts;
                if (t < tMin) tMin = t;
                if (t > tMax) tMax = t;
            }
        }
        return tMin > tMax ? null : new long[]{ tMin, tMax };
    }

    /**
     * S9's VOLUME MINI-CHART DATA — every {@link Meas#volumeCapable} reading in the
     * window, split pre/unknown vs post exactly as the measurement chart above splits its
     * own series: a post reading is swollen, and drawing it connected to the pre line
     * would show a protocol change as growth here too, the identical reason {@link
     * #buildSelectedSeries}'s own (method, phase) split exists.
     *
     * `method` on both specs is METHOD_STANDARDIZED, used purely as {@link SeriesSpec}'s
     * required field — {@link TrendChart#colorFor} ignores it for METRIC_VOL and always
     * draws {@link Look#BODY} instead (see that method's own doc for why). An empty phase
     * yields no spec for it at all, exactly like {@link #buildSelectedSeries} never adds a
     * spec with zero points.
     */
    List<SeriesSpec> volumeSeries(List<Model.Reading> oldestFirst) {
        List<SeriesSpec> out = new ArrayList<SeriesSpec>();
        List<Model.Reading> capable = Meas.volumeCapable(oldestFirst);
        List<Model.Reading> pre = Meas.preOf(capable);
        if (!pre.isEmpty()) {
            SeriesSpec s = new SeriesSpec();
            s.method = Model.Reading.METHOD_STANDARDIZED; s.phase = Model.Reading.PHASE_PRE;
            s.pts = pre;
            out.add(s);
        }
        List<Model.Reading> post = Meas.postOf(capable);
        if (!post.isEmpty()) {
            SeriesSpec s = new SeriesSpec();
            s.method = Model.Reading.METHOD_STANDARDIZED; s.phase = Model.Reading.PHASE_POST;
            s.pts = post;
            out.add(s);
        }
        return out;
    }

    // The old any-method "newest cold reading" lookup that used to live here
    // (newestCold()) is gone — its two callers (trendCard's headline, goalPaceLine's
    // fallback) both needed a reading of a SPECIFIC method/metric, not of any method, and
    // reading a mismatched method's len/gir off it was exactly the "5+ real sites" defect
    // this task fixes. trendCard now calls {@link Meas#newestColdMeasuring} per metric;
    // goalPaceLine falls back to its own GoalLine's anchor, which is already resolved to
    // the right method.

    /* --------------------------------------------------- the goal, as a sloped line */

    /** That metric's value on a reading. */
    private double metricOf(Model.Reading r) {
        return mhMetric == METRIC_LEN ? r.len : r.gir;
    }

    /**
     * ONE GOAL LINE, fully resolved: which method it belongs to, the target, and the
     * anchor (date and value) the trajectory starts from. Built by {@link #goalLines} and
     * consumed by the chart, the legend and the pace caption alike, so all three read the
     * same numbers rather than each re-deriving them.
     */
    static final class GoalLine {
        int method;
        double goalCm;
        long anchorTs;
        double anchorCm;
        /** The slope, per year, that lands ON the goal at the END of the shared horizon
         *  (Model#goalSlopePerYear) — never the raw cap, which would reach the target early
         *  and then run flat. Model#capGoal has already refused any goal steeper than the
         *  cap, so this is bounded by construction. */
        double ratePerYear;
    }

    /**
     * EVERY GOAL LINE THIS CHART SHOULD DRAW, in method order.
     *
     * A goal belongs on the plot when ALL of these hold, and the rule is asked HERE and
     * nowhere else so the chart, the legend and the caption cannot disagree:
     *   - a goal is set for that method (Model#goalForMethod);
     *   - the goal is on the metric currently drawn — a BPSSL length goal has no meaning on
     *     a girth axis, and putting it there would print a length as a circumference;
     *   - a SERIES OF THAT METHOD is currently selected. A goal is a number measured some
     *     particular way; sloping it across a differently-measured trend would put two
     *     protocols on one axis and read the gap between them as distance still to go;
     *   - the window holds a non-post reading of that method to ANCHOR to
     *     (Meas#goalAnchorOfMethod), and the goal is ABOVE it. A goal at or below the
     *     anchor has no slope to draw.
     *
     * (Note the anchor, not the latest reading: a goal that has since been REACHED still has
     * a real trajectory across this window, and drawing it is how a person sees they beat it.)
     */
    List<GoalLine> goalLines(List<Model.Reading> oldestFirst) {
        List<GoalLine> out = new ArrayList<GoalLine>();
        if (oldestFirst == null || oldestFirst.isEmpty()) return out;
        boolean wantLength = mhMetric == METRIC_LEN;
        for (int i = 0; i < Model.GOAL_METHODS.length; i++) {
            int method = Model.GOAL_METHODS[i];
            if (Model.goalMethodIsLength(method) != wantLength) continue;
            Double goal = model.goalForMethod(method);
            if (goal == null) continue;
            if (!methodPlotted(method)) continue;
            Model.Reading anc = Meas.goalAnchorOfMethod(oldestFirst, method);
            if (anc == null) continue;
            double ancV = metricOf(anc);
            if (goal.doubleValue() <= ancV) continue;
            GoalLine g = new GoalLine();
            g.method = method;
            g.goalCm = goal.doubleValue();
            g.anchorTs = anc.ts;
            g.anchorCm = ancV;
            g.ratePerYear = Model.goalSlopePerYear(ancV, goal.doubleValue(),
                                                   model.goalHorizonMonths);
            out.add(g);
        }
        return out;
    }

    /** Whether any SELECTED series is of `method`. */
    private boolean methodPlotted(int method) {
        for (java.util.Iterator<Integer> it = mhSeries.iterator(); it.hasNext(); )
            if (codeMethod(it.next().intValue()) == method) return true;
        return false;
    }

    /* --------------------------------------------- the M1 goal instrument (Task 12) */

    /**
     * ONE GOAL LINE for a SPECIFIC method, independent of whichever metric the plot above
     * is currently showing. {@link #goalLines} (above) only ever returns lines for the
     * metric mhMetric currently has selected, because it feeds the multi-series chart's own
     * axis; the M1 instrument below is a standalone card that always instruments its own
     * method's OWN dimension (length for BPSSL, girth for MSEG/MSSG) regardless of which
     * metric pill is showing, so it needs the same construction without that filter.
     *
     * Same rule {@link #goalLines} and {@link TrendChart#printGoal} already apply — a goal
     * set for the method, an anchor reading of it in this window, and the goal actually
     * above that anchor — just asked directly, since this card has no mhSeries checklist of
     * its own to consult first. Null under the same conditions those two already return
     * null for.
     */
    private GoalLine goalLineForMethod(List<Model.Reading> oldestFirst, int method) {
        if (oldestFirst == null || oldestFirst.isEmpty()) return null;
        Double goal = model.goalForMethod(method);
        if (goal == null) return null;
        Model.Reading anc = Meas.goalAnchorOfMethod(oldestFirst, method);
        if (anc == null) return null;
        boolean isLen = Model.goalMethodIsLength(method);
        double ancV = isLen ? anc.len : anc.gir;
        if (goal.doubleValue() <= ancV) return null;
        GoalLine g = new GoalLine();
        g.method = method;
        g.goalCm = goal.doubleValue();
        g.anchorTs = anc.ts;
        g.anchorCm = ancV;
        g.ratePerYear = Model.goalSlopePerYear(ancV, goal.doubleValue(),
                                               model.goalHorizonMonths);
        return g;
    }

    /**
     * THE ONE GOAL THE M1 INSTRUMENT HEADLINES, in {@link Model#GOAL_METHODS} order —
     * BPSSL, then MSEG, then MSSG — the first method that both HAS a goal and can resolve a
     * line in this window. BPSSL-first mirrors openMeasHist's own note that length is "the
     * metric this app's first chip has always been", so the one goal this card leads with
     * is the same one the rest of Progress already treats as primary when it has to pick
     * just one.
     *
     * Null when nothing qualifies — every goal unset, or every goal-bearing method's own
     * anchor missing from this particular period window — and the caller draws no card at
     * all, the same "nothing to show" null {@link #goalPaceLine} already returns.
     */
    GoalLine primaryGoalLine(List<Model.Reading> oldestFirst) {
        for (int i = 0; i < Model.GOAL_METHODS.length; i++) {
            GoalLine g = goalLineForMethod(oldestFirst, Model.GOAL_METHODS[i]);
            if (g != null) return g;
        }
        return null;
    }

    /**
     * A MULTI-SELECT of series, on one shared axis.
     *
     * The chart draws one METRIC ({@link #setMetric} — length or girth), and within it every
     * SELECTED (method, phase) SERIES as its own line: coloured per method (from
     * Look.BLOCKS), SOLID for pre/unknown and DASHED for post. All series share one vertical
     * scale — they are the same metric measured different ways, so the gaps between the
     * lines are the protocols, which is exactly the thing worth reading. Within a line the
     * stroke breaks at every incomparable boundary (Meas#drawableEdges), so a segment only
     * ever joins two directly-comparable readings.
     *
     * THE GOAL IS A SLOPE, NOT A CEILING ({@link #setGoal}). It runs from the first reading
     * of its method at the fastest rate the app will describe (Model#goalLineAt), and its
     * endpoints go through the shared scale so the gap between a trend and its pace line is
     * to scale. Drawn only when the caller has decided a series of the goal's (metric,
     * method) is on the plot.
     *
     * The PDF report drives this through {@link #setData}, which selects every series with
     * data and sets the metric's goal — the report has no chooser.
     */
    final class TrendChart extends View {
        private List<SeriesSpec> series = new ArrayList<SeriesSpec>();
        private long now;
        /** 0 length, 1 girth, 2 volume — SessionActivity#METRIC_LEN / METRIC_GIR / METRIC_VOL. */
        private int metric = METRIC_LEN;
        /** PDF report mode: the same view drawn in the Look.PRINT_* palette. */
        private final boolean print;

        /** S10+'s chart-line choice: draw {@link Meas#smoothed}'s rolling average, with the
         *  raw points faint behind it, rather than the raw line alone. Off by default —
         *  every caller that wants smoothing opts in via {@link #setSmoothed}, the same
         *  explicit-setter shape every other drawing choice here already uses. */
        private boolean smoothed = false;

        /** S9's explicit X-axis override — set by the volume mini chart so its calendar
         *  span matches the measurement chart drawn just above it EXACTLY, rather than
         *  each chart deriving its own span from whichever subset of readings IT happens
         *  to plot (the volume chart's own readings are a narrower subset — see
         *  Meas#volumeCapable — and would otherwise stretch to fill the view on their own
         *  dates, breaking the "aligned X" the S9 mock asks for). Unset, a chart derives
         *  its span from its own series exactly as it always did — this is additive, not
         *  a behaviour change for any existing caller. */
        private boolean hasTimeWindow = false;
        private long twMin, twMax;

        /** EVERY goal line to draw, already resolved by SessionActivity#goalLines — one
         *  per plotted method that has a goal on this metric. A LIST, not one line: a chart
         *  showing BPSSL and MSEG at once has two targets, and the old single-goal field
         *  could only ever show whichever one a stored preference named. */
        private List<GoalLine> goals = new ArrayList<GoalLine>();

        /** S20 B pinch-zoom state — a scale about the view's own centre plus a pan, the
         *  SAME translate-then-scale shape Align's own composition contract states for
         *  AlignView, applied here to this chart's whole drawn picture instead of to one
         *  bitmap (see #onDraw and ChartZoom's own doc for why the clamp shapes differ).
         *  Identity (1, 0, 0) is this chart's ordinary fitted drawing, so an untouched chart
         *  — every existing caller, print mode included — draws byte-for-byte as before. */
        private float zoomScale = 1f, panX = 0f, panY = 0f;
        private final ScaleGestureDetector scaleDetector;
        private float lastFocusX, lastFocusY;

        /* ---- the reset gesture: a double-tap, this chart's stand-in for AlignView's Reset
         * button — see #onTouchEvent's own doc for why a gesture rather than a button. */
        private float tapDownX, tapDownY;
        private boolean multiTouchThisGesture;
        private long lastTapTime = -1;
        private float lastTapX, lastTapY;
        private final int touchSlop;
        private final int doubleTapTimeoutMs;
        private final int doubleTapSlop;

        TrendChart(Activity a, boolean print) {
            super(a);
            this.print = print;
            setWillNotDraw(false);
            scaleDetector = new ScaleGestureDetector(a, new PinchPanListener());
            touchSlop = ViewConfiguration.get(a).getScaledTouchSlop();
            doubleTapTimeoutMs = ViewConfiguration.getDoubleTapTimeout();
            doubleTapSlop = ViewConfiguration.get(a).getScaledDoubleTapSlop();
        }

        void setMetric(int m) {
            metric = (m == METRIC_GIR) ? METRIC_GIR : (m == METRIC_VOL) ? METRIC_VOL : METRIC_LEN;
        }

        void setSeries(List<SeriesSpec> s, long asOf) { series = s; now = asOf; }

        void setSmoothed(boolean s) { smoothed = s; }

        /** The most y-axis gridlines this chart draws (polish item 14). Defaults to
         *  {@link Trace#AXIS_MAX_LINES}, the run chart's own cap, which fits this chart's
         *  usual 150dp height; the volume mini chart is shorter and sets its own smaller
         *  cap ({@link Look#VOL_CHART_AXIS_MAX_LINES}) through this setter. */
        private int axisMaxLines = Trace.AXIS_MAX_LINES;
        void setAxisMaxLines(int n) { axisMaxLines = n > 0 ? n : Trace.AXIS_MAX_LINES; }

        /** Pins the X axis to [tMin, tMax] regardless of what this chart's own series
         *  actually span — see this field's own doc above. */
        void setTimeWindow(long tMin, long tMax) { hasTimeWindow = true; twMin = tMin; twMax = tMax; }

        /** The goal lines to draw, each anchored at its own method's first reading. An
         *  empty list draws none, which is what an unset goal, an unplotted method and an
         *  already-passed anchor all reduce to upstream. */
        void setGoals(List<GoalLine> g) {
            goals = g == null ? new ArrayList<GoalLine>() : g;
        }

        /** One goal line as this view needs it, built from the model rather than from the
         *  screen's selection — the PDF report's entry point ({@link #setData}), which has
         *  no chooser and plots every series with data. Null when the metric's method has no
         *  goal, no anchor in the window, or a goal already at or below that anchor. */
        private GoalLine printGoal(List<Model.Reading> oldestFirstWindow, int method) {
            Double goal = model.goalForMethod(method);
            if (goal == null) return null;
            Model.Reading anc = Meas.goalAnchorOfMethod(oldestFirstWindow, method);
            if (anc == null) return null;
            double ancV = metric == METRIC_GIR ? anc.gir : anc.len;
            if (goal.doubleValue() <= ancV) return null;
            GoalLine g = new GoalLine();
            g.method = method;
            g.goalCm = goal.doubleValue();
            g.anchorTs = anc.ts;
            g.anchorCm = ancV;
            // The line reaches the goal exactly at the horizon's end — not the raw per-year
            // cap, which would land early and then run flat.
            g.ratePerYear = Model.goalSlopePerYear(ancV, goal.doubleValue(),
                                                   model.goalHorizonMonths);
            return g;
        }

        /** The PDF report entry point: draw the whole window, every series with data, with
         *  the metric's goal anchored at the oldest cold reading — the report has no picker,
         *  so it shows everything rather than a selection. */
        void setData(List<Model.Reading> oldestFirstWindow, long asOf) {
            List<SeriesSpec> all = new ArrayList<SeriesSpec>();
            List<int[]> avail = Meas.seriesWithData(oldestFirstWindow, metric == METRIC_LEN);
            for (int i = 0; i < avail.size(); i++) {
                SeriesSpec s = new SeriesSpec();
                s.method = avail.get(i)[0]; s.phase = avail.get(i)[1];
                s.pts = Meas.ofMethodPhase(oldestFirstWindow, s.method, s.phase);
                all.add(s);
            }
            setSeries(all, asOf);
            // EVERY goal on this metric, each anchored to its own method's first reading in
            // the window. The report shows all of them for the same reason it plots every
            // series: it has no chooser, and printing one target while the person keeps
            // three would drop two thirds of what they are working toward.
            List<GoalLine> gs = new ArrayList<GoalLine>();
            for (int i = 0; i < Model.GOAL_METHODS.length; i++) {
                int method = Model.GOAL_METHODS[i];
                if (Model.goalMethodIsLength(method) != (metric == METRIC_LEN)) continue;
                GoalLine g = printGoal(oldestFirstWindow, method);
                if (g != null) gs.add(g);
            }
            setGoals(gs);
        }

        /** The selected metric's value on one reading — length, girth, or (S9) the
         *  estimated volume of that SAME reading's length and girth together. Callers of
         *  the volume metric are responsible for only ever handing this readings that
         *  {@link Meas#hasBothDims} (see SessionActivity#volumeSeries) — this does not
         *  re-check, the same "the filter is the caller's job" contract {@link
         *  Meas#estimatedVolumeCm3} itself states. */
        private double val(Model.Reading r) {
            if (metric == METRIC_GIR) return r.gir;
            if (metric == METRIC_VOL) return Meas.estimatedVolumeCm3(r.len, r.gir);
            return r.len;
        }

        /** The selected metric's value read off ONE {@link Meas#smoothed} triple — {ts,
         *  avgLen, avgGir} — the smoothed-line counterpart to {@link #val}, so a metric is
         *  never resolved two different ways between the raw dots and the smoothed line
         *  drawn over them. Volume here is the estimate of the SMOOTHED length and girth,
         *  not a smoothing of the raw per-reading volumes — the input dimensions are
         *  averaged once, then the one cylindrical estimate is taken of that pair. */
        private double smoothedVal(double[] t) {
            if (metric == METRIC_GIR) return t[2];
            if (metric == METRIC_VOL) return Meas.estimatedVolumeCm3(t[1], t[2]);
            return t[1];
        }

        /** One series' ink: per method from Look.BLOCKS on screen, a two-ink split in
         *  print. Girth methods (6,7) are remapped so they never collide with Std (0).
         *  VOLUME (S9) is always {@link Look#BODY} — the body-measurement domain colour,
         *  not a per-method identity colour: unlike a length/girth series, a volume point
         *  is not "one protocol's line", it is a derived reading of the body itself, and
         *  {@link Look#BODY} is exactly the colour this app already reserves for that
         *  domain (its own doc: "the tape measure, the photographs, the before/after
         *  pair"). Print mode never draws volume today (no PDF caller sets METRIC_VOL),
         *  so no PRINT_* branch is needed for it. */
        private int colorFor(SeriesSpec s) {
            if (metric == METRIC_VOL) return Look.BODY;
            if (print)
                return s.phase == Model.Reading.PHASE_POST ? Look.PRINT_BODY : Look.PRINT_ACCENT;
            return methodInk(s.method);
        }

        /** ONE METHOD'S INK, stated once so a trace and its goal line cannot be drawn in
         *  two different colours. Girth methods (6, 7) are remapped so they never collide
         *  with Std (0). */
        private int methodInk(int method) {
            // Stated in Look, so the series chips above the chart draw the same ink.
            return Look.seriesInk(method);
        }

        /** The labels' gutter in px once the screen has decided it ({@link #setGutter});
         *  negative until then, and the chart measures its own. */
        private float gutterPx = -1f;

        /** Pins the left gutter the y labels sit in. The Progress card gives the
         *  measurement chart and the volume chart under it the SAME value, so both plots
         *  start at the same x and the span they share lines up (see ChartFrame). */
        void setGutter(float px) { gutterPx = px; }

        /** The gutter this chart's OWN labels need: the widest of its gridline labels
         *  (polish item 14 — there can be three to five now, not just two extremes) and
         *  {@link ChartFrame#AXIS_LABEL_FLOOR}, plus the gap. 0 with nothing to draw. */
        float neededGutter() {
            Extent e = extent();
            return e == null ? 0f : neededGutter(e, axisLabelPaint());
        }

        private float neededGutter(Extent e, Paint lbl) {
            float widest = 0f;
            for (int i = 0; i < e.tickVals.length; i++)
                widest = Math.max(widest, lbl.measureText(axisNum(e.tickVals[i], e.tickDecimals)));
            return ChartFrame.gutter(widest, lbl.measureText(ChartFrame.AXIS_LABEL_FLOOR),
                                     Ui.dp(SessionActivity.this, ChartFrame.LABEL_GAP_DP));
        }

        /** The axis-extreme labels' ink: neutral dim, right-aligned against the plot. The
         *  one Paint both the drawing and the gutter measurement use, so the room reserved
         *  is the room the text takes. */
        private Paint axisLabelPaint() {
            Paint lbl = new Paint(Paint.ANTI_ALIAS_FLAG);
            lbl.setColor(print ? Look.PRINT_DIM : Ui.DIM);
            lbl.setTextSize(Ui.dp(SessionActivity.this, 9));
            lbl.setTextAlign(Paint.Align.RIGHT);
            return lbl;
        }

        /** What one drawing spans: its time window, the value range the coordinates use,
         *  the data's own extremes the labels print, and each goal line's endpoints. Worked
         *  out in ONE place so the labels measured for the gutter are exactly the labels
         *  drawn, and the picture and its axis cannot be derived two ways. */
        private final class Extent {
            long tMin, tMax;
            double vMin, vMax, labMin, labMax;
            boolean drawGoals;
            double[] gLeft, gRight;
            /** The y-axis gridlines (polish item 14), in the STORED unit (cm or cm3) even
             *  though they are rounded in the DISPLAY one — see #toDisplayVal. vMin/vMax
             *  above are this array's own first and last value: the plot's vertical scale
             *  IS the tick range, not a separate fit the ticks are drawn inside. */
            double[] tickVals;
            /** Decimals the labels print with: the step's own ({@link Trace#tickDecimals}). */
            int tickDecimals = 1;
        }

        /** This chart's {@link Extent}, or null when no series holds a point. */
        private Extent extent() {
            // Shared ranges across every plotted point.
            int total = 0;
            long tMin = Long.MAX_VALUE, tMax = Long.MIN_VALUE;
            double vMin = Double.POSITIVE_INFINITY, vMax = Double.NEGATIVE_INFINITY;
            for (int si = 0; si < series.size(); si++) {
                List<Model.Reading> pts = series.get(si).pts;
                for (int i = 0; i < pts.size(); i++) {
                    Model.Reading r = pts.get(i);
                    double v = val(r);
                    if (r.ts < tMin) tMin = r.ts;
                    if (r.ts > tMax) tMax = r.ts;
                    if (v < vMin) vMin = v;
                    if (v > vMax) vMax = v;
                    total++;
                }
            }
            if (total == 0) return null;

            // S9's "aligned X" override: the X axis is pinned to the SAME span the
            // measurement chart above this one actually drew, not to wherever this
            // chart's own (narrower) volume-capable readings happen to start and end —
            // see #hasTimeWindow's own doc. Only the X extent is overridden; vMin/vMax
            // above stay derived from THIS chart's own plotted values, since the two
            // charts' Y axes are never meant to agree.
            if (hasTimeWindow) { tMin = twMin; tMax = twMax; }

            // Every goal line's endpoints join the shared vertical scale, so each pace line
            // and the trends are to scale against each other. Computed once, here, and
            // reused when they are stroked — deriving them twice is how a picture and its
            // own axis drift apart.
            boolean drawGoals = tMax > tMin && !goals.isEmpty();
            double[] gLeft = new double[goals.size()], gRight = new double[goals.size()];
            if (drawGoals) {
                for (int gi = 0; gi < goals.size(); gi++) {
                    GoalLine g = goals.get(gi);
                    // R11-1: at the plot's two ends, which are days now (ChartFrame#dayAnchor).
                    gLeft[gi]  = Model.goalLineAt(ChartFrame.dayAnchor(tMin), g.anchorTs,
                                                  g.anchorCm, g.goalCm, g.ratePerYear);
                    gRight[gi] = Model.goalLineAt(ChartFrame.dayAnchor(tMax), g.anchorTs,
                                                  g.anchorCm, g.goalCm, g.ratePerYear);
                    if (gLeft[gi]  < vMin) vMin = gLeft[gi];
                    if (gLeft[gi]  > vMax) vMax = gLeft[gi];
                    if (gRight[gi] < vMin) vMin = gRight[gi];
                    if (gRight[gi] > vMax) vMax = gRight[gi];
                }
            }
            Extent e = new Extent();
            e.tMin = tMin; e.tMax = tMax;
            e.drawGoals = drawGoals; e.gLeft = gLeft; e.gRight = gRight;
            e.labMin = vMin; e.labMax = vMax;

            /* THE AXIS, IN ROUND NUMBERS (polish item 14) — see Trace#rangeTicks's own doc
             * for why the run chart's zero-anchored axisTicks cannot simply be reused here.
             * Both the GRIDLINES and the COORDINATE SCALE come from the same tick array:
             * the plot's vertical span is the ticks' own first and last value, so no
             * gridline is ever drawn outside the plot, and the highest/lowest point on the
             * loudest series sits inside it with real headroom rather than jammed against
             * an edge — the same reason fullScaleKpa gives the run chart's trace headroom
             * above its peak. Ticks are worked out in the DISPLAY unit (#toDisplayVal),
             * because a round number of centimetres is not a round number of inches, then
             * converted back to the stored cm/cm3 the rest of this method already uses.
             *
             * A flat range (one reading, or several that all agree) still needs a usable
             * axis, so it is padded by one display unit before ticking. This replaces the
             * old vMax=vMin+1 guard, which padded the COORDINATE scale only and left the
             * axis LABEL at the single raw value — that discipline no longer applies now
             * that the labels ARE the axis, so the pad now goes through the same rounding
             * as everything else and a flat series gets a real round axis around it. */
            double dispLo = toDisplayVal(vMin), dispHi = toDisplayVal(vMax);
            if (dispHi <= dispLo) dispHi = dispLo + 1;
            double[] dispTicks = Trace.rangeTicks(dispLo, dispHi, axisMaxLines);
            double[] ticks = new double[dispTicks.length];
            for (int i = 0; i < dispTicks.length; i++) ticks[i] = fromDisplayVal(dispTicks[i]);
            e.tickVals = ticks;
            e.tickDecimals = Trace.tickDecimals(dispTicks);
            e.vMin = ticks[0];
            e.vMax = ticks[ticks.length - 1];
            if (e.vMax <= e.vMin) e.vMax = e.vMin + 1;   // defensive only — see rangeTicks's own n>=2 contract for a span this method always gives it
            return e;
        }

        @Override protected void onDraw(Canvas c) {
            super.onDraw(c);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0 || series.isEmpty()) return;

            // S20 B — pinch-zoom IN PLACE: translate then pinch about the view's OWN
            // centre, wrapping every draw call below exactly as-is — the composition order
            // Align's own doc states for its bitmap Matrix (translate, then scale), applied
            // here at the canvas level since this chart draws vector primitives, not one
            // bitmap. Identity (panX=0, panY=0, zoomScale=1) is a true no-op transform, so a
            // chart nobody has pinched — every screen before this task, and print mode,
            // which never receives touch events at all — draws byte-for-byte as before.
            c.save();
            c.translate(panX, panY);
            c.scale(zoomScale, zoomScale, w / 2f, h / 2f);

            // THE PLOT STARTS RIGHT OF ITS LABELS (bug B2). The axis extremes used to be
            // drawn four pixels in, ON the plot, so the oldest point sat on the low label
            // and its line ran through it. They now own a gutter: the one the screen gave
            // (shared with the chart stacked under this one, so both plots start at the
            // same x and keep one time axis), or this chart's own when nobody set one. See
            // ChartFrame's doc for the floor that keeps it from jumping between series.
            Extent e = extent();
            if (e == null) { c.restore(); return; }
            final Paint lbl = axisLabelPaint();
            float padL = gutterPx >= 0f ? gutterPx : neededGutter(e, lbl);
            float padR = Ui.dp(SessionActivity.this, ChartFrame.PLOT_RIGHT_DP);
            // padT used to be a bare 6px: enough for the OLD design, where the one top
            // label's baseline sat a full text size below it. Item 14's gridlines centre
            // EVERY label on its own line instead (gy + a third of the text size, the same
            // convention the run chart's axis draws in), so the topmost tick's label now
            // needs its own ascent's worth of room above padT or its glyphs clip against
            // the view's own top edge — worked out from the label Paint's real metrics
            // rather than guessed, so it tracks whatever text size axisLabelPaint sets.
            Paint.FontMetrics axisFm = lbl.getFontMetrics();
            float padT = Math.max(6f, -axisFm.top - lbl.getTextSize() / 3f
                                       + Ui.dp(SessionActivity.this, 2));
            float padB = 18f;
            float plotW = w - padL - padR, plotH = h - padT - padB;
            if (plotW <= 0f || plotH <= 0f) { c.restore(); return; }
            final long tMin = e.tMin, tMax = e.tMax;
            final double vMin = e.vMin, vMax = e.vMax;
            final boolean drawGoals = e.drawGoals;
            final double[] gLeft = e.gLeft, gRight = e.gRight;
            final double vspan = vMax - vMin;

            // GRIDLINES IN ROUND NUMBERS (polish item 14). Three dashed hairlines used to
            // sit at fixed quarters of the plot, unrelated to any value — just ground under
            // the shape. Each line now sits at an actual round number of the display unit
            // (Trace#rangeTicks, the same idea item 9 gave the run chart) and carries its
            // own label in the gutter B2's fix gave the axis: a solid LINE stroke, not
            // dashed, matching the run chart's own axis rather than the "ground" style this
            // plot used when the lines meant nothing.
            Paint grid = new Paint(Paint.ANTI_ALIAS_FLAG);
            grid.setColor(print ? Look.PRINT_LINE : Look.LINE);
            grid.setStyle(Paint.Style.STROKE);
            grid.setStrokeWidth(1f);
            float lblX = padL - Ui.dp(SessionActivity.this, ChartFrame.LABEL_GAP_DP);
            for (int g = 0; g < e.tickVals.length; g++) {
                float gy = padT + (float) (1 - (e.tickVals[g] - vMin) / vspan) * plotH;
                c.drawLine(padL, gy, padL + plotW, gy, grid);
                c.drawText(axisNum(e.tickVals[g], e.tickDecimals), lblX, gy + lbl.getTextSize() / 3f, lbl);
            }

            // TASK 5 — the day-cluster spine: a vertical hairline behind every calendar day
            // two or more of the CURRENTLY PLOTTED points share, gathered across EVERY
            // series at once — the dominant case is a multi-protocol sitting, which is N
            // readings across N different (method, phase) series sharing one ts, so a
            // series-at-a-time scan would never see them collide (see #buildSelectedSeries's
            // own doc). Drawn with the grid, before any goal or series ink, so it reads as
            // ground under the plot — a vertical hairline, never a value tick and never a
            // claim about the data itself, unlike the horizontal gridlines just above which
            // now are exactly that. See Meas#sameDayClusters for why the day rule is
            // PhotoCalendar#dayKey and not #dayOf.
            List<Long> allTs = new ArrayList<Long>();
            for (int si = 0; si < series.size(); si++) {
                List<Model.Reading> sp = series.get(si).pts;
                for (int i = 0; i < sp.size(); i++) allTs.add(Long.valueOf(sp.get(i).ts));
            }
            List<Meas.DayCluster> clusters = Meas.sameDayClusters(allTs);
            if (!clusters.isEmpty()) {
                Paint spine = new Paint(Paint.ANTI_ALIAS_FLAG);
                spine.setColor(print ? Look.PRINT_LINE : Look.LINE);
                spine.setStyle(Paint.Style.STROKE);
                spine.setStrokeWidth(1f);
                spine.setPathEffect(new DashPathEffect(new float[]{2f, 2f}, 0));
                Paint spineLbl = new Paint(Paint.ANTI_ALIAS_FLAG);
                spineLbl.setColor(print ? Look.PRINT_DIM : Ui.DIM);
                spineLbl.setTextSize(Ui.dp(SessionActivity.this, 8));
                spineLbl.setTextAlign(Paint.Align.CENTER);
                float spineLblY = padT + Ui.dp(SessionActivity.this, 8);
                for (int ci = 0; ci < clusters.size(); ci++) {
                    Meas.DayCluster cl = clusters.get(ci);
                    float x = ChartFrame.dayXAt(cl.repTs, tMin, tMax, padL, plotW, 0f);
                    c.drawLine(x, padT, x, padT + plotH, spine);
                    c.drawText("×" + cl.count, x, spineLblY, spineLbl);
                }
            }

            // The pace lines, under the traces (the data is the subject). One per goal, each
            // in ITS OWN METHOD'S colour — the same ink that method's trace is drawn in, so
            // a chart with two targets says which line belongs to which series without a
            // second legend lookup.
            if (drawGoals) {
                for (int gi = 0; gi < goals.size(); gi++) {
                    GoalLine g = goals.get(gi);
                    Paint gp = new Paint(Paint.ANTI_ALIAS_FLAG);
                    gp.setStyle(Paint.Style.STROKE);
                    gp.setColor(print ? Look.PRINT_ACCENT : methodInk(g.method));
                    gp.setStrokeWidth(2f);
                    gp.setPathEffect(new DashPathEffect(new float[]{3f, 4f}, 0));
                    float gy0 = padT + (float) (1 - (gLeft[gi]  - vMin) / vspan) * plotH;
                    float gyR = padT + (float) (1 - (gRight[gi] - vMin) / vspan) * plotH;
                    c.drawLine(padL, gy0, padL + plotW, gyR, gp);
                    Paint gLbl = new Paint(Paint.ANTI_ALIAS_FLAG);
                    gLbl.setColor(gp.getColor());
                    gLbl.setTextSize(Ui.dp(SessionActivity.this, 9));
                    gLbl.setAlpha(170); gLbl.setTextAlign(Paint.Align.RIGHT);
                    c.drawText(Model.Fmt.lenNum(gRight[gi]), w - padR, gyR - 3f, gLbl);
                }
            }

            // Each selected series: its own coloured line (dashed for post), broken at every
            // incomparable boundary, with a dot per reading (hollow when taken without a hold).
            // S10+: when `smoothed`, the RAW points are drawn FIRST — faint, no connecting
            // line, so they sit visually BEHIND — then the SAME series' smoothed rolling
            // average is drawn on top in full ink, exactly where the raw line/dots alone
            // used to be. `smoothed == false` is the untouched original behaviour.
            /* R11-1 - BY DAY, AND EACH DAY'S BEFORE JOINED TO ITS AFTER. Every point stands at
             * its day's x (ChartFrame#dayXAt): a before a hair left, an after a hair right, so
             * the two never hide each other, and the axis spreads only across different days.
             * The positions are worked out for every series first, so the short line from a
             * day's before to its after (same method) is drawn under the series' own ink. */
            float hair = Ui.dp(SessionActivity.this, 3);
            float[][] allPx = new float[series.size()][], allPy = new float[series.size()][];
            float[][] allPyRaw = new float[series.size()][];
            for (int si = 0; si < series.size(); si++) {
                SeriesSpec s = series.get(si);
                List<Model.Reading> pts = s.pts;
                int n = pts.size();
                float nudge = s.phase == Model.Reading.PHASE_PRE ? -hair
                            : s.phase == Model.Reading.PHASE_POST ? hair : 0f;
                float[] px = new float[n], pyRaw = new float[n];
                for (int i = 0; i < n; i++) {
                    px[i] = ChartFrame.dayXAt(pts.get(i).ts, tMin, tMax, padL, plotW, nudge);
                    pyRaw[i] = padT + (float) (1 - (val(pts.get(i)) - vMin) / vspan) * plotH;
                }
                float[] py = pyRaw;
                if (smoothed && n > 0) {
                    List<double[]> sm = Meas.smoothedWithinRuns(pts, Meas.SMOOTH_WINDOW);
                    py = new float[n];
                    for (int i = 0; i < n; i++)
                        py[i] = padT + (float) (1 - (smoothedVal(sm.get(i)) - vMin) / vspan) * plotH;
                }
                allPx[si] = px; allPy[si] = py; allPyRaw[si] = pyRaw;
            }
            drawDayJoins(c, allPx, allPy);

            for (int si = 0; si < series.size(); si++) {
                SeriesSpec s = series.get(si);
                List<Model.Reading> pts = s.pts;
                int n = pts.size();
                if (n == 0) continue;
                float[] px = allPx[si], pyRaw = allPyRaw[si];
                int col = colorFor(s);
                boolean post = s.phase == Model.Reading.PHASE_POST;

                float[] py = allPy[si];
                if (smoothed) {
                    // THE RAW ECHO, faint dots only — no path, no held/hollow distinction
                    // (that reads as a live data point, and these are deliberately
                    // background texture, not a second series to inspect). Alpha, not
                    // Look.FAINT: that constant is documented "labels and units ONLY", and
                    // these dots keep the series' OWN ink (just muted) so they read as
                    // "this same line, before smoothing" rather than a neutral grey.
                    Paint raw = new Paint(Paint.ANTI_ALIAS_FLAG);
                    raw.setColor(col);
                    raw.setAlpha(80);
                    for (int i = 0; i < n; i++) c.drawCircle(px[i], pyRaw[i], 3f, raw);
                }

                boolean[] edges = Meas.drawableEdges(pts);
                Paint line = new Paint(Paint.ANTI_ALIAS_FLAG);
                line.setStyle(Paint.Style.STROKE);
                line.setColor(col);
                line.setStrokeWidth(3.5f);
                if (post) line.setPathEffect(new DashPathEffect(new float[]{9f, 6f}, 0));
                Path path = new Path();
                for (int i = 0; i < n; i++) {
                    if (i == 0 || !edges[i]) path.moveTo(px[i], py[i]);
                    else                     path.lineTo(px[i], py[i]);
                }
                c.drawPath(path, line);

                Paint fill = new Paint(Paint.ANTI_ALIAS_FLAG);
                fill.setColor(col);
                Paint hollow = new Paint(fill);
                hollow.setStyle(Paint.Style.STROKE);
                hollow.setStrokeWidth(2.5f);
                // STUDY-19 V2: every method's dots are filled. They were hollow for every
                // reading without a hold - so every dot on every at-rest line (BPEL, MSEG...)
                // was drawn as the lesser mark. The one reading still drawn apart is a Std-line
                // reading with no hold recorded (Meas#markedApart), on its own line only.
                for (int i = 0; i < n; i++)
                    c.drawCircle(px[i], py[i], 4.5f, Meas.markedApart(pts.get(i)) ? hollow : fill);
            }

            c.restore();
        }

        /** R11-1: a short line from each day's before to that day's after, per method - the
         *  newest of each on the day, the pair Meas#prePostPct reads. Drawn in the method's
         *  ink, thinner than the series lines, so the session's change reads at a glance. */
        private void drawDayJoins(Canvas c, float[][] allPx, float[][] allPy) {
            Paint join = new Paint(Paint.ANTI_ALIAS_FLAG);
            join.setStyle(Paint.Style.STROKE);
            join.setStrokeWidth(Ui.dp(SessionActivity.this, 1) * 1.5f);
            for (int pi = 0; pi < series.size(); pi++) {
                SeriesSpec pre = series.get(pi);
                if (pre.phase != Model.Reading.PHASE_PRE) continue;
                for (int qi = 0; qi < series.size(); qi++) {
                    SeriesSpec post = series.get(qi);
                    if (post.phase != Model.Reading.PHASE_POST || post.method != pre.method)
                        continue;
                    join.setColor(colorFor(post));
                    for (int i = 0; i < pre.pts.size(); i++) {
                        int day = PhotoCalendar.dayKey(pre.pts.get(i).ts);
                        // the newest before of its day only
                        if (i + 1 < pre.pts.size()
                                && PhotoCalendar.dayKey(pre.pts.get(i + 1).ts) == day) continue;
                        int j = -1;
                        for (int k = 0; k < post.pts.size(); k++)
                            if (PhotoCalendar.dayKey(post.pts.get(k).ts) == day) j = k;
                        if (j < 0) continue;
                        c.drawLine(allPx[pi][i], allPy[pi][i], allPx[qi][j], allPy[qi][j], join);
                    }
                }
            }
        }

        /** A gridline's label for the current metric, in its display unit (cm or in per the
         *  size-unit setting for length/girth; always cm3 for volume, see
         *  {@link Model.Fmt#volNum}), with the step's own decimals: "190", not "190.0". */
        private String axisNum(double v, int decimals) {
            return String.format(java.util.Locale.US, "%." + decimals + "f", toDisplayVal(v));
        }

        /** A STORED value (cm, or cm3 for volume) as the number its axis labels are
         *  ROUNDED in — the display unit, not the text {@link #axisNum} formats. Girth and
         *  length follow {@link Model.Fmt#sizeUnit}; volume never converts (S9's cm3 is its
         *  own unit family — see {@link Model.Fmt#volNum}'s own doc). Feeds
         *  {@link Trace#rangeTicks}, which needs an actual number to round rather than
         *  formatted text, in the same unit the label will be printed in: a round
         *  centimetre is not a round inch, and ticking in cm then labelling in inches (or
         *  the reverse) would draw gridlines at numbers that only look round in the unit
         *  nobody is reading. {@link #fromDisplayVal} is its inverse. */
        private double toDisplayVal(double stored) {
            if (metric == METRIC_VOL) return stored;
            return Model.Fmt.S_IN.equals(Model.Fmt.sizeUnit) ? stored / Model.Fmt.CM_PER_IN : stored;
        }

        /** {@link #toDisplayVal}'s inverse — a rounded display-unit tick back to the
         *  stored cm/cm3 this chart's coordinate maths (vMin, vMax, val()) already uses. */
        private double fromDisplayVal(double display) {
            if (metric == METRIC_VOL) return display;
            return Model.Fmt.S_IN.equals(Model.Fmt.sizeUnit) ? display * Model.Fmt.CM_PER_IN : display;
        }

        /**
         * S20 B — pinch-zoom, ported from CameraScreen.AlignView's shape (the only other
         * pinch gesture in this app) but DELIBERATELY asymmetric with it, because this view
         * lives inside bodyScroll's vertical ScrollView rather than on a dedicated
         * full-screen editor. AlignView claims every one-finger touch on ACTION_DOWN
         * (requestDisallowInterceptTouchEvent) because its whole screen exists for that one
         * gesture; doing the same here would swallow the Progress page's own scroll the
         * instant a drag starts over a chart card — a regression this method exists to
         * avoid, not just to add a gesture.
         *
         *   - A one-finger DOWN/MOVE/UP is never claimed here at all: this method changes
         *     no scale/pan state and never touches requestDisallowInterceptTouchEvent for
         *     it, so bodyScroll's own ScrollView keeps intercepting (and scrolling) a
         *     one-finger drag over this chart exactly as it did before this class existed —
         *     TrendChart has no tap-for-detail of its own to protect either (verified: no
         *     click/touch listener was ever attached to it), so there is nothing here for a
         *     one-finger gesture to conflict with.
         *   - A SECOND finger landing (ACTION_POINTER_DOWN) is the unambiguous signal this
         *     IS a pinch, not a scroll — only then is the parent told to stop intercepting,
         *     and only while 2+ pointers are down does state actually change (see
         *     PinchPanListener, which drives both scale AND pan off the SAME
         *     ScaleGestureDetector — a chart cannot safely offer AlignView's separate
         *     one-finger pan for the reason above, so the two-finger gesture's own focus
         *     point carries the pan instead).
         *   - A one-finger DOWN/UP that never went multi-touch and never travelled past
         *     touch-slop is a tap; two of those inside the SYSTEM double-tap timeout/slop —
         *     not guessed constants, the same ViewConfiguration source AlignView's own
         *     touch-slop check reads from — reset the zoom (#maybeDoubleTap). This is the
         *     gesture equivalent of AlignView's Reset button, chosen as a gesture instead of
         *     a persistent button because AlignView is a dedicated full screen built to hold
         *     one and a 150dp chart card among a dozen others on the Progress page is not.
         *     Nothing is lost by that choice: this TrendChart instance is discarded and
         *     rebuilt from scratch — a fresh, unzoomed one — by nearly every OTHER
         *     interaction on the page (the period pill, the metric chip, the smoothed/raw
         *     chip, the series picker, navigating away and back), so a zoom that somehow
         *     cannot be double-tapped away cannot outlive the very next thing done with the
         *     rest of the screen either.
         */
        @Override public boolean onTouchEvent(MotionEvent e) {
            scaleDetector.onTouchEvent(e);
            switch (e.getActionMasked()) {
                case MotionEvent.ACTION_DOWN:
                    tapDownX = e.getX(); tapDownY = e.getY();
                    multiTouchThisGesture = false;
                    return true;
                case MotionEvent.ACTION_POINTER_DOWN:
                    multiTouchThisGesture = true;
                    if (getParent() != null) getParent().requestDisallowInterceptTouchEvent(true);
                    return true;
                case MotionEvent.ACTION_POINTER_UP:
                    // getPointerCount() here counts the departing pointer too, so ==2 means
                    // THIS lift takes it down to one finger — the ordinary pan this chart
                    // deliberately does not offer (see this method's own doc), so control
                    // reverts to the ScrollView. A three-(or more-)finger touch dropping to
                    // two must NOT release it: that is still the live pinch, and letting go
                    // here would hand a still-in-progress gesture back to the ScrollView
                    // mid-zoom.
                    if (e.getPointerCount() <= 2 && getParent() != null)
                        getParent().requestDisallowInterceptTouchEvent(false);
                    return true;
                case MotionEvent.ACTION_UP:
                    if (getParent() != null) getParent().requestDisallowInterceptTouchEvent(false);
                    maybeDoubleTap(e);
                    return true;
                case MotionEvent.ACTION_CANCEL:
                    if (getParent() != null) getParent().requestDisallowInterceptTouchEvent(false);
                    return true;
                default:
                    return true;
            }
        }

        /** One half of the reset gesture — see #onTouchEvent's own doc for why a double-tap
         *  stands in for AlignView's Reset button here. A CANDIDATE tap is a one-pointer
         *  press-and-release that never went multi-touch this gesture and never travelled
         *  past touch-slop; two candidates inside the system's own double-tap timeout AND
         *  slop reset the zoom to identity. */
        private void maybeDoubleTap(MotionEvent e) {
            if (multiTouchThisGesture) return;
            float dx = e.getX() - tapDownX, dy = e.getY() - tapDownY;
            if (Math.hypot(dx, dy) > touchSlop) return;
            long now = System.currentTimeMillis();
            if (lastTapTime >= 0
                    && now - lastTapTime <= doubleTapTimeoutMs
                    && Math.hypot(e.getX() - lastTapX, e.getY() - lastTapY) <= doubleTapSlop) {
                zoomScale = 1f; panX = 0f; panY = 0f;
                lastTapTime = -1;
                invalidate();
            } else {
                lastTapTime = now; lastTapX = e.getX(); lastTapY = e.getY();
            }
        }

        /** The two-finger gesture's own listener — scale from {@link ScaleGestureDetector}'s
         *  own factor, clamped by {@link ChartZoom#clampScale}; pan from the SAME gesture's
         *  focus-point drift between callbacks, clamped by {@link ChartZoom#clampPan} against
         *  the scale just computed — see #onTouchEvent's own doc for why pan rides on this
         *  listener rather than a separate one-finger drag. */
        private final class PinchPanListener extends ScaleGestureDetector.SimpleOnScaleGestureListener {
            @Override public boolean onScaleBegin(ScaleGestureDetector d) {
                lastFocusX = d.getFocusX(); lastFocusY = d.getFocusY();
                return true;
            }
            @Override public boolean onScale(ScaleGestureDetector d) {
                zoomScale = ChartZoom.clampScale(zoomScale * d.getScaleFactor());
                panX = ChartZoom.clampPan(panX + (d.getFocusX() - lastFocusX), zoomScale, getWidth());
                panY = ChartZoom.clampPan(panY + (d.getFocusY() - lastFocusY), zoomScale, getHeight());
                lastFocusX = d.getFocusX(); lastFocusY = d.getFocusY();
                invalidate();
                return true;
            }
        }
    }

    /* --------------------------------------------------------- reading editor */

    /**
     * Reading editor, per #v-meas-edit / editMeas()/saveMeas()/cancelMeas(), Task 8 Step 4.
     * A STAGED working copy (edWorking, a Model.Reading.copy() of the live object): every
     * stepper/toggle here mutates ONLY edWorking, never model.measLog directly. Save is the
     * one place edWorking's fields are copied onto the real reading (and `edited` set, but
     * only when Meas.changed() says something actually differs); Back/Discard just drops
     * edWorking on the floor. Writing straight into the live object on every keystroke —
     * the prototype's own fixed bug class — would make Back a silent commit.
     */
    String edId;
    Model.Reading edOriginal;
    Model.Reading edWorking;

    /** Delegates to {@link Model.MeasLog#byId} (Task 4 gave MeasLog its own id lookup,
     *  identical to what this method already did by hand — one scan, not two that could
     *  silently disagree). */
    Model.Reading findReading(String id) {
        return model.measLog.byId(id);
    }

    final class OpenMeasEditTap implements View.OnClickListener {
        private final String id;
        OpenMeasEditTap(String id) { this.id = id; }
        @Override public void onClick(View v) { showMeasEdit(id); }
    }

    /* ------------------------------------------------------------------ taps */

    final class Tap implements View.OnClickListener {
        static final int START = 1, STOP = 2, HOME = 3, SETS = 4, ROUTINES = 5,
                         DIAG = 6, RECONNECT = 7,
                         /* SELF_TEST = 11 was here. The pure harness runs on every build
                          * through test.sh, which is where it belongs; nothing ever built a
                          * Tap for it, so the case below was unreachable - and it was the
                          * app's ONLY reference to SelfTest, which dragged 26,719 lines of
                          * assertions into the shipped dex to satisfy a call nobody could
                          * make. Removing it lets build.sh leave that file out entirely. */
                         SETTINGS = 12, MEASHIST = 13, COMPARE = 14,
                         HISTORY = 15,
                         UP = 20, LO = 21, UH = 22, LH = 23, SP = 24, DUR = 25,
                         UP2 = 26, SP2 = 27, STEPS = 28, LO2 = 29,
                         UH2 = 30, LH2 = 31;
        private final int what, arg;
        Tap(int w) { this(w, 0); }
        Tap(int w, int a) { what = w; arg = a; }
        @Override public void onClick(View v) { act(what, arg); }
    }

    private final class Bump implements View.OnClickListener {
        private final int field, delta;
        Bump(int f, int d) { field = f; delta = d; }
        @Override public void onClick(View v) { bump(field, delta); }
    }

    private void act(int what, int arg) {
        switch (what) {
            case Tap.START:     confirmStart(); break;
            case Tap.STOP:      stopWithResumeOffer(); break;
            case Tap.HOME:      showHome(); break;
            case Tap.SETS:      showSets(); break;
            case Tap.ROUTINES:  showRoutines(); break;
            case Tap.RECONNECT: link.close(); syncKnownPumpsToLink(); link.start(); break;
            case Tap.DIAG:      handOffToDiagnostics(); break;
            case Tap.SETTINGS:  showSettings(); break;
            case Tap.HISTORY:   showSessionHistory(); break;
            case Tap.MEASHIST:  openMeasHist(); break;
            case Tap.COMPARE:   openCompare(); break;
            default: break;
        }
    }

    /** Opens the editor for a specific set id — a dedicated listener rather than a Tap
     *  arg, since Tap's arg is an int and set ids are strings. */
    private final class OpenSetEdit implements View.OnClickListener {
        private final String id;
        OpenSetEdit(String id) { this.id = id; }
        @Override public void onClick(View v) { showSetEdit(id); }
    }

    /** "+ New set" — creates a DRAFT and opens the editor on it. The set goes into
     *  model.sets so every existing listener resolves it normally, but it is NOT committed
     *  to disk here and it is marked as never-saved, so SAVE is what puts it in the library
     *  and leaving without saving deletes it. No more "New set" litter from a look. */
    /**
     * "▶ Try this set" — the guard, then the same consent dialog a manual run gets, then
     * {@link #beginEphemeralRun} on the editor's CURRENT values.
     *
     * THE GUARD IS THE SAME ONE EVERY OTHER RUN ENTRY POINT USES: the link has to be ready
     * (a pull with no way to send a stop is the one thing this app never does), and
     * stillUnsafe() has to be false — an earlier stop that has not been evidenced by
     * telemetry means the previous cuff state is unknown, and starting a fresh pull on top
     * of that is exactly the situation the vent watch exists for. Both refuse with a
     * sentence rather than a disabled button, so the reason is readable.
     */
    /**
     * The "run this set on its own" confirm, shared by the set editor's own Try button and
     * by a starred set on Today (F3). One dialog, one set of refusals \u2014 the connection
     * check and the unconfirmed-stop refusal are exactly the ones the editor already made,
     * and a second entry point must not be a second, weaker door.
     */
    private void confirmTrySet(final String setId) {
        final Model.Set s = model.set(setId);
        if (s == null) { showSets(); return; }
        if (link == null || !link.isReady()) { toast("Not connected to the pump"); openConnect(); return; }
        if (stillUnsafe()) {
            toast("The last stop is not confirmed yet \u2014 wait for the pump to report");
            return;
        }
        // Release review: the first start asks for notifications, once (invariant 100).
        if (askNotificationsFirst(new AfterAskTrySet(setId), true)) return;
        int peak = Manual.enforcedPeakKpa(s, model.ceilKpa);
        Ui.dress(SessionActivity.this, Ui.dialog(SessionActivity.this)
            .setTitle("Try " + s.name + "?")
            .setMessage("This RUNS THE PUMP with this set's values: peak "
                + Model.Fmt.p(peak) + ", " + Model.Fmt.t(s.dur)
                + ".\n\n"
                + "The set is not saved and not changed. STOP vents immediately.")
            .setPositiveButton("Run it", new GoTrySet(setId))
            .setNegativeButton("Cancel", null)
            .show());
    }

    /** A starred set on Today, straight into the same confirm. */
    private final class TryStarredSetTap implements View.OnClickListener {
        private final String setId;
        TryStarredSetTap(String id) { setId = id; }
        @Override public void onClick(View v) {
            if (favSheet != null) { favSheet.dismiss(); favSheet = null; }
            confirmTrySet(setId);
        }
    }

    /** The set editor's own star toggle. */
    /**
     * THE CYLINDER YOU ARE ACTUALLY USING (F18), inside the standardisation card because
     * that is the only place its dimensions mean anything to the app.
     *
     * The bore is the number that earns its keep: it is the one object of known size in a
     * standardised photo, so knowing it is what separates "these two photos are framed
     * alike" from "these two photos are to the same scale". Usable length bounds the
     * guide's height.
     *
     * A LIST, because people own two or three and switch. A reading that cannot say which
     * cylinder it was taken in cannot honestly be compared with one taken in another.
     */
    /**
     * THE RACK, GROUPED BY WHAT EACH TUBE IS FOR.
     *
     * A flat list answers "which tubes do I own"; a rack of two or three exists to answer
     * "which one do I reach for", and that is the category. The heading is derived from the
     * measured girth on every draw and never stored - as girth grows the same tube moves
     * from the girth group to the length one, and a stored label would go on claiming a
     * fit the tube no longer has.
     */
    /**
     * WHERE THE RACK EDITOR REDRAWS ITSELF. Settings owns these controls, and the trainer
     * wizard's own cylinder step borrows them — it used to print the rack as plain text,
     * so a tube minted there could not be named or sized without leaving setup for
     * Settings. Null means Settings; anything else is the screen that borrowed them.
     */
    private Runnable rackRedraw;

    private void redrawRack() {
        if (rackRedraw != null) rackRedraw.run(); else showSettings();
    }

    void cylinderRows(LinearLayout g) { cylinderRows(g, null); }

    void cylinderRows(LinearLayout g, Runnable redraw) {
        rackRedraw = redraw;
        Ui.note(this, g, "The cylinder you pump in. Its inside diameter is what lets a "
            + "standardised photo be scaled rather than merely framed alike.");
        double gir = girthNowCm();
        if (gir <= 0 && !model.cylinders.isEmpty())
            Ui.note(this, g, "Log a girth measurement and each tube can say what it is for.");

        // The groups, in the order somebody reads them: what pulls, what fits, what neither.
        // WHAT PULLS IS WHAT THE PERSON MARKED FOR LENGTH (owner, 2026-09-30); the girth
        // tubes are grouped by how they fit, as before - a girth tube in the traction band is
        // a close fit, and it does not pull until it is marked for length.
        boolean grouped = gir > 0 && model.cylinders.size() > 1;
        boolean lengthHead = false;
        for (int i = 0; i < model.cylinders.size(); i++) {
            Model.Cylinder c = model.cylinders.get(i);
            if (c == null || !c.isLength()) continue;
            if (grouped && !lengthHead) {
                Ui.microLabel(this, g, "For length \u2014 pulls", Ui.DIM);
                lengthHead = true;
            }
            cylinderRow(g, c, i, gir);
        }
        int[] bands = { Traction.FIT_TRACTION, Traction.FIT_GIRTH_IDEAL,
                        Traction.FIT_GIRTH_OVERSIZE, Traction.FIT_TOO_TIGHT,
                        Traction.FIT_TOO_LOOSE, Traction.FIT_UNKNOWN };
        String[] heads = { "Close fit", "For girth", "For girth \u2014 oversize",
                           "Too tight", "Too loose", "Not classified yet" };
        for (int b = 0; b < bands.length; b++) {
            boolean headDone = false;
            for (int i = 0; i < model.cylinders.size(); i++) {
                Model.Cylinder c = model.cylinders.get(i);
                if (c == null || c.isLength()) continue;
                int band = gir > 0 ? Traction.fit(c.boreCm, gir) : Traction.FIT_UNKNOWN;
                if (band != bands[b]) continue;
                if (grouped && !headDone) {
                    Ui.microLabel(this, g, heads[b], Ui.DIM);
                    headDone = true;
                }
                cylinderRow(g, c, i, gir);
            }
        }
        Model.Cylinder cur = model.cylinder();
        if (cur != null) {
            Ui.stepperRow(this, g, "Inside diameter", Model.Fmt.len(cur.boreCm),
                new BumpCylinderTap(0, -1), new BumpCylinderTap(0, +1));
            Ui.stepperRow(this, g, "Usable length", Model.Fmt.len(cur.lengthCm),
                new BumpCylinderTap(1, -1), new BumpCylinderTap(1, +1));
            // WHAT IT IS USED FOR (owner, 2026-09-30): a cylinder marked for length is the one
            // the length track pulls in, and its bore is what the load converts at.
            Ui.microLabel(this, g, SetupText.ED_USED_FOR, Ui.DIM);
            Ui.row(this, g,
                new String[]{
                    (cur.isLength() ? A11y.MARK_OFF : A11y.MARK_ON) + SetupText.ED_ROLE_GIRTH,
                    (cur.isLength() ? A11y.MARK_ON : A11y.MARK_OFF) + SetupText.ED_ROLE_LENGTH },
                new View.OnClickListener[]{
                    new SetCylinderRoleTap(Model.Cylinder.ROLE_GIRTH),
                    new SetCylinderRoleTap(Model.Cylinder.ROLE_LENGTH) });
        }
        Button add = Ui.flat(this, g, "+ Add a cylinder");
        add.setOnClickListener(new AddCylinderTap());
        if (!model.cylinders.isEmpty()) {
            Button del = Ui.flat(this, g, "Remove this cylinder");
            del.setTextColor(Ui.CRIT);
            del.setOnClickListener(new RemoveCylinderTap());
        }
    }

    /**
     * ONE ROW, WITH ITS OWN DERIVED LINES.
     *
     * The lines used to render for the ACTIVE cylinder only, once, under the whole list - so
     * a rack of three told you what one of them was for and left the other two as a bore and
     * a fit chip. Every row now carries its own, which is the point of a rack.
     */
    private void cylinderRow(LinearLayout g, Model.Cylinder c, int i, double gir) {
        boolean active = i == model.activeCylinder;
        String name = cylinderNameOf(c);
        Button row = Ui.flat(this, g, (active ? "\u25cf " : "\u25cb ")
            + name + "   " + c.line() + cylinderFitTag(c));
        row.setContentDescription(name + ", " + c.line() + cylinderFitTag(c)
            + (active ? ", in use" : ", tap to use"));
        row.setOnClickListener(new PickCylinderTap(i));

        Button ren = Ui.flat(this, g, "    Rename \u203a");
        ren.setTextColor(Ui.DIM);
        ren.setContentDescription("Rename " + name);
        ren.setOnClickListener(new RenameCylinderTap(i));

        if (gir > 0) {
            String room = cylinderRoomLine(c);
            if (room != null) Ui.note(this, g, room);
            cylinderFitLines(g, c);
        } else if (c.isLength()) {
            cylinderFitLines(g, c);     // a length tube's pull needs no girth (its bore)
        }
    }

    /** "Used for" on the cylinder in use - the old rack's own control for the role. */
    private final class SetCylinderRoleTap implements View.OnClickListener {
        private final String role;
        SetCylinderRoleTap(String r) { role = r; }
        @Override public void onClick(View v) {
            Model.Cylinder c = model.cylinder();
            if (c == null) return;
            c.role = role;
            c.clamp();
            Store.save(SessionActivity.this, model);
            redrawRack();
        }
    }

    /**
     * THE RACK'S DERIVED LINES WITHOUT ITS CONTROLS - for the trainer's setup, which draws the
     * first-run setup's cylinder cards (SetupKit) and keeps under them what those cards do not
     * say: each tube's fit at the logged girth, its room, and for a length tube the pull and
     * the limit that binds it; for an oversize girth tube, the reduction (0.10).
     */
    void cylinderFitNotes(LinearLayout g) { cylinderFitNotes(g, model, false); }

    /**
     * The same, with the plan's limits read from `basis` - the trainer setup's own answers (a
     * scratch model, TrainerScreen#onboardScratch) rather than the plan on file: a 7-month L3
     * person setting up was told "The 1.8 kg cap is what limits the load here", the first
     * month's cap of the default plan not yet written (device walk, E-I1). The rack and the
     * logged girth are the model's either way.
     */
    void cylinderFitNotes(LinearLayout g, Model basis) { cylinderFitNotes(g, basis, true); }

    /**
     * The same; `setupFace` for the trainer setup's step 4, which folds each cylinder's notes
     * into their first sentence (device check EMU9 M6): a LENGTH cylinder leads with what it
     * can pull - "At your ceiling this cylinder can pull up to 7.9 kg." - and never with the
     * girth room line, which is a girth cylinder's figure.
     */
    void cylinderFitNotes(LinearLayout g, Model basis, boolean setupFace) {
        if (model.cylinders.isEmpty()) return;
        if (basis == null) basis = model;
        double gir = girthNowCm();
        boolean girthTubes = false;
        for (int i = 0; i < model.cylinders.size(); i++) {
            Model.Cylinder c = model.cylinders.get(i);
            if (c == null || c.boreCm <= 0) continue;
            // A LENGTH TUBE SAYS WHAT IT PULLS WITHOUT A GIRTH (owner, 2026-09-30): the load
            // is worked out from its bore. Only its fit warning waits for a girth.
            if (gir <= 0 && !c.isLength()) { girthTubes = true; continue; }
            Ui.microLabel(this, g, cylinderNameOf(c) + cylinderFitTag(c), Ui.DIM);
            if (setupFace && c.isLength()) {
                Ui.note(this, g, "At your ceiling this cylinder can pull "
                    + Traction.boundLb(Traction.deviceMaxLbAtBore(c.boreCm,
                        Math.min(basis.ceilKpa, Plan.ABSOLUTE_CAP_KPA))) + ".");
            } else {
                String room = cylinderRoomLine(c);
                if (room != null) Ui.note(this, g, room);
            }
            cylinderFitLines(g, c, basis);
        }
        if (girthTubes)
            Ui.note(this, g, "Log a girth measurement and each girth tube can say how it fits.");
    }

    /** Renaming goes through a dialog rather than an inline field, for the reason
     *  EditMeasNoteTap already states: this screen rebuilds on every stepper tap, which
     *  would drop focus and the keyboard out from under an inline EditText. */
    private final class RenameCylinderTap implements View.OnClickListener {
        private final int idx;
        RenameCylinderTap(int i) { idx = i; }
        @Override public void onClick(View v) {
            if (idx < 0 || idx >= model.cylinders.size()) return;
            Model.Cylinder c = model.cylinders.get(idx);
            EditText input = new EditText(SessionActivity.this);
            // A HINT, not a contentDescription: a hint is announced as the field's label and
            // does not replace what the user has typed.
            input.setHint("what you call this tube");
            input.setText(c.label);
            input.setSelection(input.getText().length());
            Ui.dress(SessionActivity.this, Ui.dialog(SessionActivity.this)
                .setTitle("Rename cylinder")
                .setView(input)
                .setPositiveButton("Save", new RenameCylinderConfirm(idx, input))
                .setNegativeButton("Cancel", null)
                .show());
        }
    }

    private final class RenameCylinderConfirm implements DialogInterface.OnClickListener {
        private final int idx;
        private final EditText input;
        RenameCylinderConfirm(int i, EditText e) { idx = i; input = e; }
        @Override public void onClick(DialogInterface d, int w) {
            if (idx < 0 || idx >= model.cylinders.size()) return;
            // AN EMPTY NAME IS A CLEARED NAME, not a blank row: cylinderNameOf falls back to
            // the position, so somebody who wants the default back gets it by emptying the
            // field rather than by having to guess what it was called.
            model.cylinders.get(idx).label = input.getText().toString().trim();
            Store.save(SessionActivity.this, model);
            redrawRack();
        }
    }

    /**
     * "your last girth 12.4 cm → 3.9 across · 1.1 cm of room", or null when there is no
     * girth to say it with.
     *
     * The girth is a CIRCUMFERENCE, so the width across is girth / π. Both numbers go
     * through Fmt.len so the line follows the length unit like every other measurement in
     * the app, rather than hard-coding centimetres into one sentence.
     *
     * Null, not a placeholder, when nothing has been measured: a row reading "— of room"
     * states a fact about a measurement that does not exist.
     */
    /**
     * The fit band as a short, neutral tag for a rack row.
     *
     * "" when there is no measured girth to derive it against: a guess about which tube is
     * which is worse than silence, and the row below already prompts for the measurement.
     * This is a CLASSIFICATION, not a warning - it says what the cylinder is for.
     */
    private String cylinderFitTag(Model.Cylinder c) {
        double gir = girthNowCm();
        // Marked for length: that is what it is for, whatever the girth (the fit warns below).
        if (c != null && c.isLength()) return "   \u00b7  for length";
        if (c == null || c.boreCm <= 0 || gir <= 0) return "";
        return "   \u00b7  " + Traction.fitLabel(Traction.fit(c.boreCm, gir));
    }

    /**
     * WHAT THIS CYLINDER IS, in the numbers each track actually cares about.
     *
     * The two tracks read a bore in opposite directions, which is why one line cannot serve
     * both: on girth a wider bore is GENTLER, on traction force goes as diameter squared, so a
     * wider bore is HARDER. A girth cylinder therefore gets its circumference margin (and the
     * petechiae reduction when it is oversize); a traction tube gets the load it can actually
     * pull and WHICH ceiling stops it - "turn it up" being useless advice against a pump that
     * is already at its own limit.
     *
     * Every figure here comes from {@link Traction}; nothing is multiplied out at this call
     * site.
     */
    /**
     * HAS THIS TUBE DRIFTED FROM A GIRTH FIT TO A LENGTH ONE?
     *
     * Derived, never stored - storing it would be storing a fit, which this app refuses. The
     * comparison is against the OLDEST erect girth reading logged while this cylinder was the
     * one in use: if the tube classified as a girth cylinder at that girth and pulls at
     * today's, the tissue has grown into it and the rack should say so.
     *
     * FALSE when there is no such reading, which is honest silence rather than a guess: the
     * tube may simply be new, and "it fits like a length tube NOW" is a claim about a past
     * that would not exist.
     */
    private boolean cylinderHasDrifted(Model.Cylinder c, double girNow) {
        if (c == null || c.boreCm <= 0 || girNow <= 0) return false;
        if (!Traction.pulls(Traction.fit(c.boreCm, girNow))) return false;
        double oldest = 0;
        for (int i = 0; i < model.measLog.all.size(); i++) {
            Model.Reading r = model.measLog.all.get(i);
            if (r.gir <= 0 || r.method != Model.Reading.METHOD_MSEG) continue;
            if (r.cylinderId == null || !r.cylinderId.equals(c.id)) continue;
            oldest = r.gir;                    // the log is newest-first, so this ends oldest
        }
        if (oldest <= 0) return false;
        int then = Traction.fit(c.boreCm, oldest);
        return then == Traction.FIT_GIRTH_IDEAL || then == Traction.FIT_GIRTH_OVERSIZE;
    }

    private void cylinderFitLines(LinearLayout g, Model.Cylinder c) {
        cylinderFitLines(g, c, model);
    }

    /** The same, a length tube's limits read from `basis` (cylinderFitNotes). */
    private void cylinderFitLines(LinearLayout g, Model.Cylinder c, Model basis) {
        if (c == null || c.boreCm <= 0) return;
        double gir = girthNowCm();
        if (c.isLength()) { lengthTubeLines(g, c, gir, basis); return; }
        if (gir <= 0) {
            Ui.note(this, g, "Log a girth measurement and this will say what the cylinder is "
                + "for \u2014 the fit is worked out from your girth, not from the bore alone.");
            return;
        }
        int band = Traction.fit(c.boreCm, gir);
        if (band == Traction.FIT_GIRTH_IDEAL || band == Traction.FIT_GIRTH_OVERSIZE) {
            Ui.note(this, g, "Its bore circumference is about "
                + String.format(Locale.US, "%.0f", Traction.overGirthPct(c.boreCm, gir))
                + " % over your girth \u2014 a girth cylinder.");
            if (band == Traction.FIT_GIRTH_OVERSIZE)
                Ui.note(this, g, "Wide enough that the guidance is to run "
                    + Say.hgUnder(Plan.BIG_CYLINDER_HG) + " under while you are in it.");
        } else if (band == Traction.FIT_TRACTION) {
            /* "ABOUT 11.8 lb" HEDGED THE WRONG THING. The arithmetic is exact; what is
             * uncertain is how much of it reaches the tissue. "About" reads as "roughly
             * this much tension", which is the one claim this figure may not make. */
            /* HAS IT DRIFTED? The spec asks the rack to say "fits like a length tube NOW
             * - size up for girth work", which is a statement about CHANGE. The app cannot
             * store the old band (never store derived fit), so it re-derives it against the
             * OLDEST erect girth this tube ever has a reading beside: if it used to classify
             * as a girth tube at that girth and pulls at this one, the tissue has grown into
             * it. Silence when there is no such reading is honest silence - the tube may be
             * new, and claiming drift would be inventing a history. */
            /* A GIRTH TUBE THAT FITS CLOSELY no longer pulls by its size alone (owner,
             * 2026-09-30): the length track pulls in the cylinder marked for length. */
            boolean drifted = cylinderHasDrifted(c, gir);
            Ui.note(this, g, drifted
                ? "It fits like a length tube NOW \u2014 your girth has grown into it. "
                  + "Size up for girth work, or mark this one for length to pull in it."
                : "It fits closely enough to pull \u2014 mark it for length to pull in it.");
        } else if (band == Traction.FIT_TOO_TIGHT) {
            Ui.note(this, g, "Narrower than your girth \u2014 too tight to seal, and not a fit "
                + "to pull in.");
        } else if (band == Traction.FIT_TOO_LOOSE) {
            Ui.note(this, g, "Far wider than your girth: it neither grips enough to pull nor "
                + "loads the tissue evenly.");
        }
    }

    /**
     * A CYLINDER MARKED FOR LENGTH (owner, 2026-09-30): it pulls, and what it pulls is worked
     * out from its BORE - so these lines need no girth. With a girth logged, the fit check
     * WARNS when the tube is looser or tighter than a traction fit; it no longer stops it.
     */
    private void lengthTubeLines(LinearLayout g, Model.Cylinder c, double gir, Model basis) {
        String warn = Model.lengthFitWarning(gir > 0 ? Traction.fit(c.boreCm, gir)
                                                     : Traction.FIT_UNKNOWN);
        if (warn.length() > 0) Ui.note(this, g, warn);
        else if (gir > 0) Ui.note(this, g, "It fits closely enough to pull \u2014 a length tube.");
        if (c.boreCm > 0) {
            Ui.note(this, g, "At your ceiling of " + Model.Fmt.p(basis.ceilKpa)
                + " the vacuum can pull " + Traction.boundLb(Traction.deviceMaxLbAtBore(
                        c.boreCm, Math.min(basis.ceilKpa, Plan.ABSOLUTE_CAP_KPA)))
                + " in it; friction at the seal takes some of that.");
            /* AND THE REACH AT A FIXED REFERENCE, which the spec asks for by name. Worded so
             * it cannot be mistaken for a promise: a 40 kPa ceiling cannot reach 15 inHg, and
             * a line that quoted the figure flatly would advertise a pull this app will never
             * command. */
            double ref = Plan.ABSOLUTE_CAP_KPA;
            if (basis.ceilKpa < ref - 0.5)
                Ui.note(this, g, "At the pump's own limit of " + Model.Fmt.p(ref)
                    + " it would be " + Traction.boundLb(Traction.deviceMaxLbAtBore(c.boreCm, ref))
                    + ", if your ceiling allowed it.");
            /* THE LIMIT THAT IS ACTUALLY IN FORCE (t10 device walk M6). Twelve pounds is the
             * plan's usual load, not its cap - a climb takes the pull past it, warned once
             * before month 12 - and fifteen is hard (a new person's first month, four). This
             * line called twelve "the cap" beside a proposed start above it. Said by
             * Scale#loadLimitLine, the one wording, in the person's load unit. */
            int month = TrainerTab.monthIndexNow(basis, System.currentTimeMillis());
            Ui.note(this, g, Scale.loadLimitLine(Scale.isNew(basis), month, c.boreCm,
                basis.ceilKpa));
        }
    }

    /**
     * The girth every derived cylinder line is measured against - the most recent reading that
     * actually carries one, or 0 when none does.
     *
     * The log is descending by ts, so the first reading that HAS a girth is the newest; one
     * logged with length only is not evidence of girth. 0 means "not measured yet", which
     * callers must render as a prompt to measure rather than as a fit.
     */
    private double girthNowCm() { return model.girthForTraction(); }

    private String cylinderRoomLine(Model.Cylinder c) {
        if (c == null || c.boreCm <= 0) return null;
        double gir = girthNowCm();
        if (gir <= 0) return null;
        double across = gir / Math.PI;
        double room = c.boreCm - across;
        return "your last girth " + Model.Fmt.len(gir) + "  →  "
             + Model.Fmt.len(across) + " across  ·  "
             + (room >= 0 ? Model.Fmt.len(room) + " of room"
                          : Model.Fmt.len(-room) + " wider than the bore");
    }

    private final class PickCylinderTap implements View.OnClickListener {
        private final int idx;
        PickCylinderTap(int i) { idx = i; }
        @Override public void onClick(View v) {
            model.activeCylinder = idx;
            Store.save(SessionActivity.this, model);
            redrawRack();
        }
    }

    /** One tap moves a dimension by a tenth of a centimetre \u2014 fine enough to describe a
     *  real cylinder, coarse enough that setting one is not a chore. */
    private final class BumpCylinderTap implements View.OnClickListener {
        private final int which, dir;
        BumpCylinderTap(int w, int d) { which = w; dir = d; }
        @Override public void onClick(View v) {
            Model.Cylinder c = model.cylinder();
            if (c == null) return;
            if (which == 0) c.boreCm += 0.1 * dir; else c.lengthCm += 0.1 * dir;
            c.boreCm = Math.rint(c.boreCm * 10.0) / 10.0;
            c.lengthCm = Math.rint(c.lengthCm * 10.0) / 10.0;
            c.clamp();
            Store.save(SessionActivity.this, model);
            redrawRack();
        }
    }

    private final class AddCylinderTap implements View.OnClickListener {
        @Override public void onClick(View v) {
            /* THE FIRST UNUSED NUMBER, not the count plus one. After deleting "Cylinder 2"
             * from a rack of three, the count-based name minted a SECOND "Cylinder 3" - two
             * rows with the same name, and the only thing telling them apart a bore. */
            int n = model.cylinders.size() + 1;
            for (int k = 1; k <= model.cylinders.size() + 1; k++) {
                boolean taken = false;
                for (int q = 0; q < model.cylinders.size(); q++)
                    if (("Cylinder " + k).equals(model.cylinders.get(q).label)) taken = true;
                if (!taken) { n = k; break; }
            }
            addCylinder("Cylinder " + n, 5.0, 23.0);
            redrawRack();
        }
    }

    /** A new cylinder in the rack, clamped, with its id, made the active one and saved -
     *  shared with the first-run setup's cylinder editor. */
    Model.Cylinder addCylinder(String label, double boreCm, double lengthCm) {
        return addCylinder(label, boreCm, lengthCm, Model.Cylinder.defaultRole(label));
    }

    /** The same with what it is used for (Model.Cylinder#role) - the cylinder sheet's. */
    Model.Cylinder addCylinder(String label, double boreCm, double lengthCm, String role) {
        Model.Cylinder c = new Model.Cylinder(label, boreCm, lengthCm);
        c.role = role;
        c.clamp();
        model.cylinders.add(c);
        // Minted HERE, not left to the next load: a reading taken against an id-less
        // cylinder would have nothing but its index to be reconstructed from, and a
        // deletion before the next load is exactly the case that reconstruction gets wrong.
        model.ensureCylinderIds();
        model.activeCylinder = model.cylinders.size() - 1;
        Store.save(this, model);
        return c;
    }

    private final class RemoveCylinderTap implements View.OnClickListener {
        @Override public void onClick(View v) {
            Model.Cylinder c = model.cylinder();
            if (c == null) return;
            Ui.dress(SessionActivity.this, Ui.dialog(SessionActivity.this)
                .setTitle("Remove this cylinder?")
                .setMessage("Readings already taken keep the dimensions they were taken "
                    + "with. Only future ones are affected.")
                .setPositiveButton("Remove", new RemoveCylinderConfirm())
                .setNegativeButton("Cancel", null)
                .show());
        }
    }

    private final class RemoveCylinderConfirm implements DialogInterface.OnClickListener {
        @Override public void onClick(DialogInterface d, int w) {
            if (model.cylinders.isEmpty()) return;
            int i = model.activeCylinder;
            if (i < 0 || i >= model.cylinders.size()) i = 0;
            model.cylinders.remove(i);
            model.activeCylinder = 0;
            Store.save(SessionActivity.this, model);
            redrawRack();
        }
    }

